function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _tryOrderCancellation(uint256 amount) internal {
        IBloomPool pool = _bloomPool;
        uint256 amountOpen = pool.amountOpen(address(this));

        // Cancel open lend orders if there are any
        if (amountOpen > 0) {
            uint256 killAmount = Math.min(amountOpen, amount);
            pool.killOpenOrder(killAmount);
            amount -= killAmount;
        }

        // If more liquidity is needed, cancel matched orders
        if (amount > 0) {
            uint256 amountMatched = pool.amountMatched(address(this));
            if (amountMatched > 0) {
                uint256 killAmount = Math.min(amountMatched, amount);
                pool.killMatchOrder(killAmount);
                amount -= killAmount;
            }
        }
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }

business_flow_context:
function redeemWstUsdc(uint256 amount) external override returns (uint256 assetsRedeemed) {
        _burn(msg.sender, amount);
        uint256 stUsdcAmount = _stUsdc.usdByShares(amount);
        assetsRedeemed = _stUsdc.redeemStUsdc(stUsdcAmount);
        _stUsdcAsset.safeTransfer(msg.sender, assetsRedeemed);
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }
function sharesByUsd(uint256 usdAmount) public view override returns (uint256) {
        return _sharesByAmount(usdAmount);
    }
function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }
function balanceOf(address account) public view override returns (uint256) {
        return _amountByShares(_shares[account]);
    }
function _burnShares(address account, uint256 sharesAmount) internal virtual returns (uint256 newTotalShares) {
        require(account != address(0), Errors.ZeroAddress());

        uint256 accountShares = _shares[account];
        require(sharesAmount <= accountShares, Errors.InsufficientBalance());

        uint256 preRebaseTokenAmount = _amountByShares(sharesAmount);

        newTotalShares = _totalShares - sharesAmount;
        _totalShares = newTotalShares;

        _shares[account] = accountShares - sharesAmount;

        uint256 postRebaseTokenAmount = _amountByShares(sharesAmount);

        _emitTransferEvents(account, address(0), postRebaseTokenAmount, sharesAmount);
    }
function _stake(address user, uint256 amount) internal nonReentrant {
        StakingData storage data = _stakingData[user];
        require(amount != 0, Errors.ZeroTokensStaked());

        data.amountStaked += uint128(amount);
        _totalStakeUpStaked += amount;

        emit StakeUpStaked(user, amount);
        IERC20(address(_stakeupToken)).safeTransferFrom(msg.sender, address(this), amount);
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }
function processFees() public payable override onlyStUsdc nonReentrant updateIndex {
        // solhint-ignore-previous-line no-empty-blocks
    }
function stake(uint256 stakeupAmount) external override updateIndex distributeRewards {
        _lastDeposit[msg.sender] = block.timestamp;
        _stake(msg.sender, stakeupAmount);
    }
function sharesByUsd(uint256 usdAmount) public view override returns (uint256) {
        return _sharesByAmount(usdAmount);
    }
function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function mint(address to, uint256 amount) public initialized onlyOwner {
        _updateGlobalSupply(amount);
        _mint(to, amount);
    }
function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }
function _mintShares(address recipient, uint256 sharesAmount) internal virtual returns (uint256 newTotalShares) {
        require(recipient != address(0), Errors.ZeroAddress());

        newTotalShares = _totalShares + sharesAmount;
        _totalShares = newTotalShares;

        _shares[recipient] = _shares[recipient] + sharesAmount;
        _emitTransferEvents(address(0), recipient, _amountByShares(sharesAmount), sharesAmount);
    }

