contract_code:
{
    using OFTComposeMsgCodec for bytes32;

    // =================== Storage ===================
    /// @dev Address of stUsdc contract
    address private immutable _stUsdc;

    // =================== Modifiers ===================
    modifier onlyStUsdc() {
        if (msg.sender != _stUsdc) revert Errors.UnauthorizedCaller();
        _;
    }

    // ================= Constructor =================
    constructor(address stUsdc_, address layerZeroEndpoint, address bridgeOperator)
        LzOrderedMessenger(layerZeroEndpoint, bridgeOperator)
    {
        _stUsdc = stUsdc_;
    }

    // =================== Functions ===================
    /**
     * @notice Syncs all stUsdc instances with the newUsdPerShare value
     * @param newUsdPerShare The new USD per share to be set in the stUsdc contract
     * @param timestamp The timestamp that the newUsdPerShare is set at
     * @param peerEids An array of peer endpoint ids
     * @param options LayerZero messaging options
     * @param refundRecipient The address to refund any excess native fee to
     */
    function sync(
        uint256 newUsdPerShare,
        uint256 timestamp,
        uint32[] memory peerEids,
        bytes memory options,
        address refundRecipient
    ) external payable onlyStUsdc returns (MessagingReceipt[] memory receipts) {
        return _batchSend(abi.encode(newUsdPerShare, timestamp), peerEids, options, refundRecipient);
    }

    // ========================= Quote Functions =========================
    /**
     * @notice Quotes the fee for syncing all stUsdc instances with the newUsdPerShare value
     * @param expectedUsdPerShare The new USD per share to be set in the stUsdc contract
     * @param peerEids An array of peer endpoint ids
     * @param options LayerZero messaging options
     * @return nativeFee The amount of native fee estimated for syncing all stUsdc instances
     */
    function quoteSync(uint256 expectedUsdPerShare, uint32[] memory peerEids, bytes memory options)
        external
        view
        returns (uint256 nativeFee)
    {
        return _quoteMessage(expectedUsdPerShare, peerEids, options);
    }

    /// @notice Returns the address of the stUsdc contract
    function stUsdc() external view returns (address) {
        return _stUsdc;
    }

    /**
     * @notice Quotes the fee for sending a message to instances on other chains
     * @param expectedUsdPerShare The expected USD per share to be set in the stUsdc contract
     * @param peerEids An array of peer endpoint ids
     * @param options LayerZero messaging options
     */
    function _quoteMessage(uint256 expectedUsdPerShare, uint32[] memory peerEids, bytes memory options)
        internal
        view
        returns (uint256 nativeFee)
    {
        uint256 length = peerEids.length;
        for (uint256 i = 0; i < length; ++i) {
            MessagingFee memory fee =
                _quote(peerEids[i], abi.encode(expectedUsdPerShare, block.timestamp), options, false);
            nativeFee += fee.nativeFee;
        }
    }

    /**
     * @notice Batch sends a message to multiple StakeUpMessenger instances on other chains
     * @param message The encoded message data to send
     * @param peerEids An array of peer endpoint ids
     * @param options LayerZero messaging options
     */
    function _batchSend(bytes memory message, uint32[] memory peerEids, bytes memory options, address refundRecipient)
        internal
        returns (MessagingReceipt[] memory receipts)
    {
        uint256 providedFee = msg.value;

        uint256 length = peerEids.length;
        receipts = new MessagingReceipt[](length);

        for (uint256 i = 0; i < length; ++i) {
            MessagingReceipt memory receipt =
                _lzSend(peerEids[i], message, options, MessagingFee(providedFee, 0), address(this));
            providedFee -= receipt.fee.nativeFee;
            receipts[i] = receipt;
        }

        // If there is excess fee, refund it to the refundRecipient
        if (providedFee > 0) {
            payable(refundRecipient).transfer(providedFee);
        }
    }

    /**
     * @notice Receives the message an associated StakeUpMessenger instance on another chain
     *         And makes the necessary relay call to the stUsdc contract
     */
    function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata _message,
        address _executor,
        bytes calldata _extraData
    ) internal virtual override {
        super._lzReceive(_origin, _guid, _message, _executor, _extraData);
        (uint256 newUsdPerShare, uint256 timestamp) = _decodeUsdPerShare(_message);
        IStUsdc(_stUsdc).setUsdPerShare(newUsdPerShare, timestamp);
    }

    /**
     * @notice Decodes the encoded data for share update message types
     * @param encodedData The encoded data to decode
     */
    function _decodeUsdPerShare(bytes memory encodedData) internal pure returns (uint256, uint256) {
        return abi.decode(encodedData, (uint256, uint256));
    }
}

business_flow_code:
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function _quoteMessage(uint256 expectedUsdPerShare, uint32[] memory peerEids, bytes memory options)
        internal
        view
        returns (uint256 nativeFee)
    {
        uint256 length = peerEids.length;
        for (uint256 i = 0; i < length; ++i) {
            MessagingFee memory fee =
                _quote(peerEids[i], abi.encode(expectedUsdPerShare, block.timestamp), options, false);
            nativeFee += fee.nativeFee;
        }
    }

business_flow_context:
function redeemWstUsdc(uint256 amount) external override returns (uint256 assetsRedeemed) {
        _burn(msg.sender, amount);
        uint256 stUsdcAmount = _stUsdc.usdByShares(amount);
        assetsRedeemed = _stUsdc.redeemStUsdc(stUsdcAmount);
        _stUsdcAsset.safeTransfer(msg.sender, assetsRedeemed);
    }
function depositAsset(uint256 amount) external override returns (uint256 amountMinted) {
        _stUsdcAsset.safeTransferFrom(msg.sender, address(this), amount);
        _stUsdcAsset.safeApprove(address(_stUsdc), amount);
        amountMinted = _stUsdc.depositAsset(amount);
        amountMinted = _mintWstUsdc(amountMinted);
    }
function _transferRewards(address user) internal {
        RewardData storage rewards = _rewardData;
        StakingData storage data = _stakingData[user];

        uint128 rewardsEarned = data.rewardsAccrued;
        if (rewardsEarned > 0) {
            data.rewardsAccrued = 0;
            rewards.lastShares -= rewardsEarned;
            _stUsdc.transferShares(user, rewardsEarned);
        }
    }
function depositTby(uint256 tbyId, uint256 amount) external override returns (uint256 amountMinted) {
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
        amountMinted = _stUsdc.depositTby(tbyId, amount);

        uint256 supStartBalance = _sup.balanceOf(address(this));
        amountMinted = _mintWstUsdc(amountMinted);

        // If SUP rewards have been minted, transfer to the user
        uint256 supEndBalance = _sup.balanceOf(address(this));
        if (supEndBalance > supStartBalance) {
            uint256 supMinted = supEndBalance - supStartBalance;
            _sup.safeTransfer(msg.sender, supMinted);
        }
    }
function stUsdcPerToken() external view returns (uint256) {
        return _stUsdc.usdByShares(1 ether);
    }
function bridgeByEid(uint32 eid) external view returns (bytes32) {
        return _wstUsdcBridges[eid];
    }
function _bridgeStUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 stUsdcAmount,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) internal returns (LzBridgeReceipt memory bridgingReceipt) {
        SendParam memory sendParam =
            _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings.options);

        (MessagingReceipt memory msgReceipt, OFTReceipt memory oftReceipt) =
            IOFT(_stUsdc).send{value: msg.value}(sendParam, settings.fee, settings.refundRecipient);

        bridgingReceipt = LzBridgeReceipt(msgReceipt, oftReceipt);
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function _updateRewardIndex() internal returns (uint256) {
        if (_lastRewardBlock != block.number) {
            _lastRewardBlock = block.number;

            uint256 totalStakeUpLocked = _totalStakeUpStaked + _totalStakeUpVesting;
            RewardData storage rewards = _rewardData;

            uint256 accrued = _stUsdc.sharesOf(address(this)) - rewards.lastShares;

            if (rewards.index == 0) {
                rewards.index = uint128(Constants.INITIAL_REWARD_INDEX);
            }

            if (totalStakeUpLocked != 0) {
                rewards.index += uint128(accrued.divWad(totalStakeUpLocked));
            }

            rewards.lastShares = uint128(rewards.lastShares + accrued);

            return rewards.index;
        } else {
            return _rewardData.index;
        }
    }
function _setSendParam(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 amount,
        uint256 wstUsdcAmount,
        bytes calldata options
    ) internal view returns (SendParam memory) {
        bytes32 wstUsdcBridge = _wstUsdcBridges[dstEid];
        require(wstUsdcBridge != bytes32(0), Errors.ZeroAddress());

        return SendParam({
            dstEid: dstEid,
            to: wstUsdcBridge,
            amountLD: amount,
            minAmountLD: amount,
            extraOptions: options,
            composeMsg: abi.encode(destinationAddress, wstUsdcAmount),
            oftCmd: ""
        });
    }
function _setDelegates(address newDelegate) internal {
        require(newDelegate != address(0), Errors.ZeroAddress());
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).forceSetDelegate(newDelegate);
        ControllerBase(supToken).forceSetDelegate(newDelegate);
        ControllerBase(wstUsdcBridge).forceSetDelegate(newDelegate);
        ControllerBase(keeper).forceSetDelegate(newDelegate);
    }
function _setPeers(uint32 eid, bytes32[4] memory peers) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        IOAppCore(stUsdc).setPeer(eid, peers[0]);
        IOAppCore(supToken).setPeer(eid, peers[1]);
        IOAppCore(wstUsdcBridge).setPeer(eid, peers[2]);
        IOAppCore(keeper).setPeer(eid, peers[3]);
    }
function lzCompose(
        address _oApp,
        bytes32, /*_guid*/
        bytes calldata _message,
        address, /*Executor*/
        bytes calldata /*Executor Data*/
    ) external payable override {
        if (_oApp != _stUsdc) revert Errors.InvalidOApp();
        if (msg.sender != address(endpoint)) revert Errors.UnauthorizedCaller();

        bytes memory _composeMsgContent = OFTComposeMsgCodec.composeMsg(_message);

        (bytes32 destinationAddressBytes32, uint256 wstUsdcAmount) = abi.decode(_composeMsgContent, (bytes32, uint256));
        address destinationAddress = destinationAddressBytes32.bytes32ToAddress();

        bool success = _deliverWstUsdc(destinationAddress, wstUsdcAmount);
        if (!success) revert Errors.LZComposeFailed();
    }
function wstUsdcByStUsdc(uint256 stUsdcAmount) external view returns (uint256) {
        return _stUsdc.sharesByUsd(stUsdcAmount);
    }
function unwrap(uint256 wstUsdcAmount) external returns (uint256 stUsdcAmount) {
        stUsdcAmount = _stUsdc.usdByShares(wstUsdcAmount);
        require(stUsdcAmount > 0, Errors.ZeroAmount());

        _burn(msg.sender, wstUsdcAmount);
        StUsdcLite(address(_stUsdc)).transferShares(msg.sender, wstUsdcAmount);
        emit WstUsdcUnwrapped(msg.sender, wstUsdcAmount, stUsdcAmount);
    }
function tokensPerStUsdc() external view returns (uint256) {
        return _stUsdc.sharesByUsd(1 ether);
    }
function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }
function _setBridgeOperator(address newBridgeOperator) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).setBridgeOperator(newBridgeOperator);
        ControllerBase(supToken).setBridgeOperator(newBridgeOperator);
        ControllerBase(wstUsdcBridge).setBridgeOperator(newBridgeOperator);
        ControllerBase(keeper).setBridgeOperator(newBridgeOperator);
    }
function setWstUsdcBridge(uint32 eid, bytes32 bridge) external onlyOwner {
        require(bridge != bytes32(0), Errors.ZeroAddress());
        (,, address wstUsdcBridge,) = _decodeContracts();
        IWstUsdcBridge(wstUsdcBridge).setWstUsdcBridge(eid, bridge);
    }
function wstUsdc() external view returns (IWstUsdc) {
        return _wstUsdc;
    }
function bridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) external payable returns (LzBridgeReceipt memory bridgingReceipt) {
        require(destinationAddress != bytes32(0), Errors.ZeroAddress());
        require(wstUsdcAmount > 0, Errors.ZeroAmount());

        _wstUsdc.transferFrom(msg.sender, address(this), wstUsdcAmount);
        uint256 stUsdcAmount = _wstUsdc.unwrap(wstUsdcAmount);

        emit WstUsdcBridged(endpoint.eid(), dstEid, wstUsdcAmount);
        bridgingReceipt = _bridgeStUsdc(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings);
    }
function wrap(uint256 stUsdcAmount) external returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _mintWstUsdc(stUsdcAmount);
        ERC20(address(_stUsdc)).transferFrom(msg.sender, address(this), stUsdcAmount);
        emit StUsdcWrapped(msg.sender, stUsdcAmount, wstUsdcAmount);
    }
function stUsdcByWstUsdc(uint256 wstUsdcAmount) external view returns (uint256) {
        return _stUsdc.usdByShares(wstUsdcAmount);
    }
function _decodeContracts()
        internal
        view
        returns (address stUsdc, address supToken, address wstUsdcBridge, address keeper)
    {
        return abi.decode(_stakeUpContracts, (address, address, address, address));
    }
function wstUsdc() external view returns (address) {
        return address(_wstUsdc);
    }
function _mintWstUsdc(uint256 amount) internal returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _stUsdc.sharesByUsd(amount);
        require(wstUsdcAmount > 0, Errors.ZeroAmount());
        _mint(msg.sender, wstUsdcAmount);
    }
function quoteBridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        bytes calldata options
    ) external view returns (MessagingFee memory fee) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        SendParam memory sendParam = _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, options);
        return IOFT(_stUsdc).quoteSend(sendParam, false);
    }
function stUsdc() external view override returns (IStUsdc) {
        return _stUsdc;
    }
function setWstUsdcBridge(uint32 eid, bytes32 bridge) external override onlyBridgeOperator {
        require(eid != 0, Errors.InvalidPeerID());
        require(bridge != bytes32(0), Errors.ZeroAddress());
        _wstUsdcBridges[eid] = bridge;
        emit WstUsdcBridgeSet(eid, bridge);
    }
function _deliverWstUsdc(address destinationAddress, uint256 wstUsdcAmount) internal returns (bool) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        IERC20(_stUsdc).approve(address(_wstUsdc), stUsdcAmount);
        wstUsdcAmount = _wstUsdc.wrap(stUsdcAmount);
        return _wstUsdc.transfer(destinationAddress, wstUsdcAmount);
    }
function stUsdc() external view override returns (IStUsdc) {
        return _stUsdc;
    }
function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function peerEids() external view returns (uint32[] memory) {
        return _peerEids;
    }

content:
function stakeUpToken() external view returns (IStakeUpToken) {
        return _stakeupToken;
    }

contract_code:
{
    using Math for uint256;
    using SafeERC20 for IERC20;
    using SafeERC20 for IWstUsdc;

    // =================== Storage ===================
    /// @dev The total amount of stUsdc shares in circulation on all chains
    uint256 internal _globalShares;

    /// @dev Mint rewards remaining
    uint256 internal _mintRewardsRemaining;

    /// @notice Amount of rewards remaining to be distributed to users for poking the contract
    uint256 private _pokeRewardsRemaining;

    /// @dev Last redeemed tbyId
    uint256 internal _lastRedeemedTbyId;

    /// @dev Highest usdPerShare value used to calculate the performance fee
    uint256 internal _highestUsdPerShare;

    /// @dev The pending fee to be distributed during the next poke
    uint256 internal _pendingFee;

    // ================== Immutables ===================
    /// @dev Underlying token
    IERC20 private immutable _asset;

    /// @dev TBY Contract
    ERC1155 private immutable _tby;

    /// @dev BloomPool Contract
    IBloomPool private immutable _bloomPool;

    /// @notice WstUsdc token
    IWstUsdc private immutable _wstUsdc;

    /// @dev StakeUp Staking Contract
    IStakeUpStaking private immutable _stakeupStaking;

    /// @dev SUP Token Contract
    IStakeUpToken private immutable _stakeupToken;

    /// @dev Deployment timestamp
    uint256 private immutable _startTimestamp;

    /// @dev Scaling factor for underlying token
    uint256 private immutable _scalingFactor;

    /// @dev Underlying token decimals
    uint8 private immutable _assetDecimals;

    // ================== Constructor ==================

    constructor(
        address asset_,
        address bloomPool_,
        address stakeupStaking_,
        address wstUsdc_,
        address layerZeroEndpoint,
        address bridgeOperator
    ) StUsdcLite(layerZeroEndpoint, bridgeOperator) {
        require(asset_ != address(0) && stakeupStaking_ != address(0) && wstUsdc_ != address(0), Errors.ZeroAddress());

        _asset = IERC20(asset_);
        _assetDecimals = IERC20Metadata(asset_).decimals();

        require(IBloomPool(bloomPool_).asset() == asset_, Errors.InvalidAsset());
        _bloomPool = IBloomPool(bloomPool_);
        _tby = ERC1155(IBloomPool(bloomPool_).tby());

        _stakeupStaking = IStakeUpStaking(stakeupStaking_);
        _stakeupToken = IStakeUpStaking(stakeupStaking_).stakupToken();
        _wstUsdc = IWstUsdc(wstUsdc_);

        _scalingFactor = 10 ** (18 - _assetDecimals);
        _startTimestamp = block.timestamp;

        _pokeRewardsRemaining = Constants.POKE_REWARDS;
        _mintRewardsRemaining = StakeUpMintRewardLib._getMintRewardAllocation();

        // On the first redemption we will increment this value to overflow and start at 0.
        _lastRedeemedTbyId = type(uint256).max;
        _highestUsdPerShare = Math.WAD;
    }

    // =================== Functions ==================

    /// @inheritdoc IStUsdc
    function depositAsset(uint256 amount) external nonReentrant returns (uint256 amountMinted) {
        require(amount > 0, Errors.ZeroAmount());
        amountMinted = amount * _scalingFactor;

        _deposit(amountMinted);
        emit AssetDeposited(msg.sender, amount);
        _openLendOrder(amount);
    }

    /// @inheritdoc IStUsdc
    function depositTby(uint256 tbyId, uint256 amount) external nonReentrant returns (uint256 amountMinted) {
        IBloomPool pool = _bloomPool;
        require(amount > 0, Errors.ZeroAmount());
        require(!pool.isTbyRedeemable(tbyId), Errors.RedeemableTbyNotAllowed());

        amountMinted = _calculateTbyMintAmount(pool, tbyId, amount);

        _deposit(amountMinted);
        // Calculate & mint SUP mint rewards to users.
        _mintRewards(pool, tbyId, amount);

        emit TbyDeposited(msg.sender, tbyId, amount, amountMinted);
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
    }

    /// @inheritdoc IStUsdc
    function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }

    /// @inheritdoc IStUsdc
    function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }

    /**
     * @notice Calculate the performance fee for the protocol
     * @param yieldPerShare The yield per share
     * @param globalShares_ The total number of shares
     * @return The performance fee that will be distributed to StakeUpStaking
     */
    function _calculateFee(uint256 yieldPerShare, uint256 globalShares_) private pure returns (uint256) {
        uint256 totalYield = yieldPerShare.mulWad(globalShares_);
        return (totalYield * Constants.PERFORMANCE_BPS) / Constants.BPS_DENOMINATOR;
    }

    /**
     * @notice Open a lend order in the Bloom Pool.
     * @param amount The amount of liquidity to lend.
     */
    function _openLendOrder(uint256 amount) internal {
        IBloomPool pool = _bloomPool;
        IERC20(_asset).safeTransferFrom(msg.sender, address(this), amount);
        _asset.safeApprove(address(pool), amount);
        pool.lendOrder(amount);
    }

    /**
     * @notice Accounting logic for handling underlying asset and tby deposits.
     * @param amount The amount stUsdc being minted.
     */
    function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }

    /**
     * @notice Calculate the amount of stUsdc to mint for a given amount of TBYs
     * @dev We must discount the TBY rate by the _rewardPerSecond * sharesAmount to prevent premature reward distribution.
     * @param pool The Bloom Pool contract
     * @param tbyId The TBY ID
     * @param amount The amount of TBYs deposited
     * @return The amount of stUsdc to mint
     */
    function _calculateTbyMintAmount(IBloomPool pool, uint256 tbyId, uint256 amount) internal view returns (uint256) {
        uint256 tbyStart = pool.tbyMaturity(tbyId).start;
        uint256 rate = pool.getRate(tbyId);

        // If the TBY has been minted for more than 24 hours and is greater than 1e18, then we discount the rate by a factor of 24 hours.
        //   (if the rate is greater than 1e18)
        uint256 timeElapsed = block.timestamp - tbyStart;
        if (timeElapsed > Constants.ONE_DAY) {
            if (rate > Math.WAD) {
                uint256 adjustedRate =
                    Math.WAD + ((rate - Math.WAD).mulWad(timeElapsed - Constants.ONE_DAY).divWad(timeElapsed));
                return amount.mulWad(adjustedRate) * _scalingFactor;
            }
            return amount.mulWad(rate) * _scalingFactor;
        }

        // If the TBY has been minted for less than or equal to 24 hours, then we mint 1:1
        return (rate >= Math.WAD) ? amount * _scalingFactor : amount.mulWad(rate) * _scalingFactor;
    }

    /**
     * @notice Mints SUP rewards to the depositor
     * @dev Mint rewards are only eligible for users who deposit TBYs into the contract
     * @param pool The Bloom Pool contract
     * @param tbyId The TBY ID
     * @param amount The amount of TBYs deposited
     */
    function _mintRewards(IBloomPool pool, uint256 tbyId, uint256 amount) internal {
        uint256 mintRewardsRemaining = _mintRewardsRemaining;
        if (mintRewardsRemaining > 0) {
            uint256 maxRewards = _calculateRewards(pool, tbyId, amount);
            uint256 eligibleAmount = Math.min(maxRewards, mintRewardsRemaining);
            _mintRewardsRemaining -= eligibleAmount;
            _stakeupToken.mintRewards(msg.sender, eligibleAmount);
        }
    }

    /**
     * @notice Distributes fees to StakeUp Staking
     * @param fee The fee amount in USD scaled to 1e18.
     */
    function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }

    /**
     * @notice Attempt to cancel an open lend order and/or matched orders to free access liquidity.
     * @param amount The amount of liquidity needed.
     */
    function _tryOrderCancellation(uint256 amount) internal {
        IBloomPool pool = _bloomPool;
        uint256 amountOpen = pool.amountOpen(address(this));

        // Cancel open lend orders if there are any
        if (amountOpen > 0) {
            uint256 killAmount = Math.min(amountOpen, amount);
            pool.killOpenOrder(killAmount);
            amount -= killAmount;
        }

        // If more liquidity is needed, cancel matched orders
        if (amount > 0) {
            uint256 amountMatched = pool.amountMatched(address(this));
            if (amountMatched > 0) {
                uint256 killAmount = Math.min(amountMatched, amount);
                pool.killMatchOrder(killAmount);
                amount -= killAmount;
            }
        }
    }

    /**
     * @notice Auto lend USDC by opening a lend order in the Bloom Pool
     * @dev Auto lend feature can only be invoked every 24 hours
     * @param pool The Bloom Pool contract
     */
    function _autoLendAsset(IBloomPool pool) internal {
        uint256 amount = _asset.balanceOf(address(this));
        if (amount > 0) {
            _asset.safeApprove(address(pool), amount);
            pool.lendOrder(amount);
            emit AssetAutoLent(amount);
        }
    }

    /**
     * @notice Calculate the protocol value of assets and TBYs backed by the contract.
     * @return value The protocol value of assets and TBYs in USD scaled to 1e18.
     */
    function _protocolValue(IBloomPool pool) internal view returns (uint256 value) {
        value += pool.amountOpen(address(this));
        value += pool.amountMatched(address(this));
        value += _liveTbyValue(pool);
        value *= _scalingFactor;
    }

    /**
     * @notice Calculate the value of live TBYs backed by the contract.
     * @param pool The Bloom Pool contract.
     * @return value The value of live TBYs in USD in terms of the underlying asset.
     */
    function _liveTbyValue(IBloomPool pool) internal view returns (uint256 value) {
        uint256 startingId = lastRedeemedTbyId();
        // Because we start at type(uint256).max, we need to increment and overflow to 0.
        unchecked {
            startingId++;
        }
        uint256 lastMintedId = pool.lastMintedId();
        if (lastMintedId == type(uint256).max) return 0;
        for (uint256 i = startingId; i <= lastMintedId; ++i) {
            value += pool.getRate(i).mulWad(_tby.balanceOf(address(this), i));
        }
    }

    /// @notice Harvests the next TbyId that is ready for redemption.
    function _harvest() internal {
        IBloomPool pool = _bloomPool;
        uint256 tbyId = lastRedeemedTbyId();
        // Because we start at type(uint256).max, we need to increment and overflow to 0.
        unchecked {
            tbyId++;
        }
        bool isRedeemable = pool.isTbyRedeemable(tbyId);
        if (!isRedeemable) return;

        // Since users can't deposit TBYs that are redeemable, we can update the last redeemed TBY ID.
        _lastRedeemedTbyId = tbyId;

        uint256 amount = _tby.balanceOf(address(this), tbyId);
        if (amount == 0) return;

        // Redeem TBYs
        pool.redeemLender(tbyId, amount);
    }

    /// @notice Calulates and mints SUP rewards to users who have poked the contract
    function _distributePokeRewards() internal {
        if (_pokeRewardsRemaining > 0) {
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                Constants.POKE_REWARDS, _startTimestamp, _pokeRewardsRemaining, false
            );

            if (amount > 0) {
                amount = Math.min(amount, _pokeRewardsRemaining);
                _pokeRewardsRemaining -= amount;
                IStakeUpToken(_stakeupToken).mintRewards(msg.sender, amount);
            }
        }
    }

    /**
     * @notice Calculates the maximum amount of mint rewards for a user depositing TBYs
     * @dev There is an inverse relationship between the amount of time a TBY has been minted and the amount of rewards a user can earn.
     * @dev This calculation method is used in order to prevent users from gaming the rewards system.
     * @param pool The Bloom Pool contract
     * @param tbyId The TBY ID
     * @param amount The amount of TBYs deposited
     * @return The maximum rewards eligible for a user depositing TBYs
     */
    function _calculateRewards(IBloomPool pool, uint256 tbyId, uint256 amount) internal view returns (uint256) {
        IBloomPool.TbyMaturity memory maturity = pool.tbyMaturity(tbyId);

        uint256 timeElapsed = block.timestamp - maturity.start;
        uint256 percentMature = timeElapsed.divWad(maturity.end - maturity.start);
        percentMature = percentMature >= Math.WAD ? Math.WAD : percentMature;

        uint256 scaledAmount = amount * _scalingFactor;
        uint256 rewardsAbandoned = scaledAmount.mulWad(percentMature);

        return scaledAmount - rewardsAbandoned;
    }

    /// @inheritdoc IStUsdc
    function asset() external view returns (IERC20) {
        return _asset;
    }

    /// @inheritdoc IStUsdc
    function tby() external view returns (ERC1155) {
        return _tby;
    }

    /// @inheritdoc IStUsdc
    function wstUsdc() external view returns (IWstUsdc) {
        return _wstUsdc;
    }

    /// @inheritdoc IStUsdc
    function bloomPool() external view returns (IBloomPool) {
        return _bloomPool;
    }

    /// @inheritdoc IStUsdc
    function stakeUpStaking() external view returns (IStakeUpStaking) {
        return _stakeupStaking;
    }

    /// @inheritdoc IStUsdc
    function stakeUpToken() external view returns (IStakeUpToken) {
        return _stakeupToken;
    }

    /// @inheritdoc IStUsdc
    function performanceBps() external pure returns (uint256) {
        return Constants.PERFORMANCE_BPS;
    }

    /// @inheritdoc IStUsdc
    function globalShares() external view override returns (uint256) {
        return _globalShares;
    }

    /// @inheritdoc IStUsdc
    function lastRedeemedTbyId() public view returns (uint256) {
        return _lastRedeemedTbyId;
    }

    /// @inheritdoc IStUsdc
    function pendingFee() external view returns (uint256) {
        return _pendingFee;
    }
}

business_flow_code:
function stakeUpToken() external view returns (IStakeUpToken) {
        return _stakeupToken;
    }
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }

business_flow_context:
function _stake(address user, uint256 amount) internal nonReentrant {
        StakingData storage data = _stakingData[user];
        require(amount != 0, Errors.ZeroTokensStaked());

        data.amountStaked += uint128(amount);
        _totalStakeUpStaked += amount;

        emit StakeUpStaked(user, amount);
        IERC20(address(_stakeupToken)).safeTransferFrom(msg.sender, address(this), amount);
    }
function stake(uint256 stakeupAmount) external override updateIndex distributeRewards {
        _lastDeposit[msg.sender] = block.timestamp;
        _stake(msg.sender, stakeupAmount);
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }
function sharesByUsd(uint256 usdAmount) public view override returns (uint256) {
        return _sharesByAmount(usdAmount);
    }
function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function mint(address to, uint256 amount) public initialized onlyOwner {
        _updateGlobalSupply(amount);
        _mint(to, amount);
    }
function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }
function _mintShares(address recipient, uint256 sharesAmount) internal virtual returns (uint256 newTotalShares) {
        require(recipient != address(0), Errors.ZeroAddress());

        newTotalShares = _totalShares + sharesAmount;
        _totalShares = newTotalShares;

        _shares[recipient] = _shares[recipient] + sharesAmount;
        _emitTransferEvents(address(0), recipient, _amountByShares(sharesAmount), sharesAmount);
    }

