function globalShares() external view override returns (uint256) {
        return _globalShares;
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function _distributePokeRewards() internal {
        if (_pokeRewardsRemaining > 0) {
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                Constants.POKE_REWARDS, _startTimestamp, _pokeRewardsRemaining, false
            );

            if (amount > 0) {
                amount = Math.min(amount, _pokeRewardsRemaining);
                _pokeRewardsRemaining -= amount;
                IStakeUpToken(_stakeupToken).mintRewards(msg.sender, amount);
            }
        }
    }
function _autoLendAsset(IBloomPool pool) internal {
        uint256 amount = _asset.balanceOf(address(this));
        if (amount > 0) {
            _asset.safeApprove(address(pool), amount);
            pool.lendOrder(amount);
            emit AssetAutoLent(amount);
        }
    }

business_flow_context:
function setUsdPerShare(uint256 usdPerShare, uint256 timestamp) external onlyKeeper {
        _setUsdPerShare(usdPerShare, timestamp);
    }
function lastUsdPerShare() external view returns (uint256) {
        return _lastUsdPerShare;
    }
function _setUsdPerShare(uint256 usdPerShare, uint256 timestamp) internal {
        // solidify the yield from the last 24 hours (stored as floor which will be used to update totalUsdFloor)
        uint256 floor = _totalUsd();
        _lastRateUpdate = timestamp;

        uint256 lastUsdPerShare_ = _lastUsdPerShare;
        if (usdPerShare > lastUsdPerShare_) {
            uint256 yieldPerShare = usdPerShare - lastUsdPerShare_;
            _rewardPerSecond = yieldPerShare.divWad(Constants.ONE_DAY);
        } else if (usdPerShare < lastUsdPerShare_) {
            _rewardPerSecond = 0;
            floor = usdPerShare.mulWad(_totalShares);
        }

        _setTotalUsdFloor(floor);
        _lastUsdPerShare = usdPerShare;
        emit UpdatedUsdPerShare(usdPerShare);
    }
function lastRateUpdate() public view returns (uint256) {
        return _lastRateUpdate;
    }
function harvest() public nonReentrant updateIndex {
        uint256 rewardAmount = _distributeRewards(msg.sender);
        require(rewardAmount != 0, Errors.NoRewardsToClaim());
        emit RewardsHarvested(msg.sender, rewardAmount);
        _transferRewards(msg.sender);
    }
function peerEids() external view returns (uint32[] memory) {
        return _peerEids;
    }
function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }
function sync(
        uint256 newUsdPerShare,
        uint256 timestamp,
        uint32[] memory peerEids,
        bytes memory options,
        address refundRecipient
    ) external payable onlyStUsdc returns (MessagingReceipt[] memory receipts) {
        return _batchSend(abi.encode(newUsdPerShare, timestamp), peerEids, options, refundRecipient);
    }
function stake(uint256 stakeupAmount) external override updateIndex distributeRewards {
        _lastDeposit[msg.sender] = block.timestamp;
        _stake(msg.sender, stakeupAmount);
    }
function mintRewards(address recipient, uint256 amount) external override initialized onlyAuthorized {
        _updateGlobalSupply(amount);
        _mint(recipient, amount);
    }
function mint(address to, uint256 amount) public initialized onlyOwner {
        _updateGlobalSupply(amount);
        _mint(to, amount);
    }
function _stake(address user, uint256 amount) internal nonReentrant {
        StakingData storage data = _stakingData[user];
        require(amount != 0, Errors.ZeroTokensStaked());

        data.amountStaked += uint128(amount);
        _totalStakeUpStaked += amount;

        emit StakeUpStaked(user, amount);
        IERC20(address(_stakeupToken)).safeTransferFrom(msg.sender, address(this), amount);
    }
function balanceOf(address account) public view override returns (uint256) {
        return _amountByShares(_shares[account]);
    }

