function pendingFee() external view returns (uint256) {
        return _pendingFee;
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }

business_flow_context:
function setUsdPerShare(uint256 usdPerShare, uint256 timestamp) external onlyKeeper {
        _setUsdPerShare(usdPerShare, timestamp);
    }
function lastUsdPerShare() external view returns (uint256) {
        return _lastUsdPerShare;
    }
function _setUsdPerShare(uint256 usdPerShare, uint256 timestamp) internal {
        // solidify the yield from the last 24 hours (stored as floor which will be used to update totalUsdFloor)
        uint256 floor = _totalUsd();
        _lastRateUpdate = timestamp;

        uint256 lastUsdPerShare_ = _lastUsdPerShare;
        if (usdPerShare > lastUsdPerShare_) {
            uint256 yieldPerShare = usdPerShare - lastUsdPerShare_;
            _rewardPerSecond = yieldPerShare.divWad(Constants.ONE_DAY);
        } else if (usdPerShare < lastUsdPerShare_) {
            _rewardPerSecond = 0;
            floor = usdPerShare.mulWad(_totalShares);
        }

        _setTotalUsdFloor(floor);
        _lastUsdPerShare = usdPerShare;
        emit UpdatedUsdPerShare(usdPerShare);
    }
function lastRateUpdate() public view returns (uint256) {
        return _lastRateUpdate;
    }
function harvest() public nonReentrant updateIndex {
        uint256 rewardAmount = _distributeRewards(msg.sender);
        require(rewardAmount != 0, Errors.NoRewardsToClaim());
        emit RewardsHarvested(msg.sender, rewardAmount);
        _transferRewards(msg.sender);
    }
function peerEids() external view returns (uint32[] memory) {
        return _peerEids;
    }
function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }
function sync(
        uint256 newUsdPerShare,
        uint256 timestamp,
        uint32[] memory peerEids,
        bytes memory options,
        address refundRecipient
    ) external payable onlyStUsdc returns (MessagingReceipt[] memory receipts) {
        return _batchSend(abi.encode(newUsdPerShare, timestamp), peerEids, options, refundRecipient);
    }
function _stake(address user, uint256 amount) internal nonReentrant {
        StakingData storage data = _stakingData[user];
        require(amount != 0, Errors.ZeroTokensStaked());

        data.amountStaked += uint128(amount);
        _totalStakeUpStaked += amount;

        emit StakeUpStaked(user, amount);
        IERC20(address(_stakeupToken)).safeTransferFrom(msg.sender, address(this), amount);
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }
function processFees() public payable override onlyStUsdc nonReentrant updateIndex {
        // solhint-ignore-previous-line no-empty-blocks
    }
function stake(uint256 stakeupAmount) external override updateIndex distributeRewards {
        _lastDeposit[msg.sender] = block.timestamp;
        _stake(msg.sender, stakeupAmount);
    }
function sharesByUsd(uint256 usdAmount) public view override returns (uint256) {
        return _sharesByAmount(usdAmount);
    }
function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function mint(address to, uint256 amount) public initialized onlyOwner {
        _updateGlobalSupply(amount);
        _mint(to, amount);
    }
function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }
function _mintShares(address recipient, uint256 sharesAmount) internal virtual returns (uint256 newTotalShares) {
        require(recipient != address(0), Errors.ZeroAddress());

        newTotalShares = _totalShares + sharesAmount;
        _totalShares = newTotalShares;

        _shares[recipient] = _shares[recipient] + sharesAmount;
        _emitTransferEvents(address(0), recipient, _amountByShares(sharesAmount), sharesAmount);
    }

content:
function lzCompose(
        address _oApp,
        bytes32, /*_guid*/
        bytes calldata _message,
        address, /*Executor*/
        bytes calldata /*Executor Data*/
    ) external payable override {
        if (_oApp != _stUsdc) revert Errors.InvalidOApp();
        if (msg.sender != address(endpoint)) revert Errors.UnauthorizedCaller();

        bytes memory _composeMsgContent = OFTComposeMsgCodec.composeMsg(_message);

        (bytes32 destinationAddressBytes32, uint256 wstUsdcAmount) = abi.decode(_composeMsgContent, (bytes32, uint256));
        address destinationAddress = destinationAddressBytes32.bytes32ToAddress();

        bool success = _deliverWstUsdc(destinationAddress, wstUsdcAmount);
        if (!success) revert Errors.LZComposeFailed();
    }

contract_code:
{
    using OFTComposeMsgCodec for bytes32;

    // =================== Storage ===================
    /// @notice mapping of LayerZero Endpoint IDs to WstUsdcBridge instances
    mapping(uint32 => bytes32) private _wstUsdcBridges;

    // =================== Immutables ===================
    /// @notice Address of stUsdc contract
    address private immutable _stUsdc;

    /// @notice Address of wstUsdc contract
    WstUsdcLite private immutable _wstUsdc;

    // ================= Constructor =================
    constructor(address wstUsdc_, address layerZeroEndpoint, address bridgeOperator)
        OAppController(layerZeroEndpoint, bridgeOperator)
    {
        _wstUsdc = WstUsdcLite(wstUsdc_);
        _stUsdc = address(WstUsdcLite(wstUsdc_).stUsdc());
    }

    // =================== Functions ===================
    /// @inheritdoc IWstUsdcBridge
    function bridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) external payable returns (LzBridgeReceipt memory bridgingReceipt) {
        require(destinationAddress != bytes32(0), Errors.ZeroAddress());
        require(wstUsdcAmount > 0, Errors.ZeroAmount());

        _wstUsdc.transferFrom(msg.sender, address(this), wstUsdcAmount);
        uint256 stUsdcAmount = _wstUsdc.unwrap(wstUsdcAmount);

        emit WstUsdcBridged(endpoint.eid(), dstEid, wstUsdcAmount);
        bridgingReceipt = _bridgeStUsdc(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings);
    }

    /// @inheritdoc IWstUsdcBridge
    function setWstUsdcBridge(uint32 eid, bytes32 bridge) external override onlyBridgeOperator {
        require(eid != 0, Errors.InvalidPeerID());
        require(bridge != bytes32(0), Errors.ZeroAddress());
        _wstUsdcBridges[eid] = bridge;
        emit WstUsdcBridgeSet(eid, bridge);
    }

    /// @inheritdoc IWstUsdcBridge
    function quoteBridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        bytes calldata options
    ) external view returns (MessagingFee memory fee) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        SendParam memory sendParam = _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, options);
        return IOFT(_stUsdc).quoteSend(sendParam, false);
    }

    /// @inheritdoc IWstUsdcBridge
    function stUsdc() external view returns (address) {
        return _stUsdc;
    }

    /// @inheritdoc IWstUsdcBridge
    function wstUsdc() external view returns (address) {
        return address(_wstUsdc);
    }

    /// @inheritdoc IWstUsdcBridge
    function bridgeByEid(uint32 eid) external view returns (bytes32) {
        return _wstUsdcBridges[eid];
    }

    /**
     * @notice Bridges stUsdc tokens to the destination wstUsdc Bridge contract
     * @param dstEid The destination LayerZero Endpoint ID
     * @param destinationAddress The address to send the bridged wstUsdc to (casted to bytes32)
     * @param stUsdcAmount The unwrapped amount of stUsdc to bridge
     * @param wstUsdcAmount The amount of wstUsdc to bridge
     * @param settings Configuration settings for bridging using LayerZero
     * @return bridgingReceipt LzBridgeReceipt Receipts for bridging using LayerZero
     */
    function _bridgeStUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 stUsdcAmount,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) internal returns (LzBridgeReceipt memory bridgingReceipt) {
        SendParam memory sendParam =
            _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings.options);

        (MessagingReceipt memory msgReceipt, OFTReceipt memory oftReceipt) =
            IOFT(_stUsdc).send{value: msg.value}(sendParam, settings.fee, settings.refundRecipient);

        bridgingReceipt = LzBridgeReceipt(msgReceipt, oftReceipt);
    }

    /**
     * @notice Delivers wstUsdc tokens to the destination address
     * @param destinationAddress The address to send the bridged wstUsdc to
     * @param wstUsdcAmount The wrapped amount of wstUsdc to deliver (Same as shares of wstUsdc to wrap)
     */
    function _deliverWstUsdc(address destinationAddress, uint256 wstUsdcAmount) internal returns (bool) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        IERC20(_stUsdc).approve(address(_wstUsdc), stUsdcAmount);
