function _transferShares(address sender, address recipient, uint256 sharesAmount) internal {
        require(sender != address(0), Errors.ZeroAddress());
        require(recipient != address(0), Errors.ZeroAddress());

        uint256 currentSenderShares = _shares[sender];
        require(sharesAmount <= currentSenderShares, Errors.InsufficientBalance());

        _shares[sender] = currentSenderShares - sharesAmount;
        _shares[recipient] = _shares[recipient] + sharesAmount;
    }
function _emitTransferEvents(address from, address to, uint256 tokenAmount, uint256 sharesAmount) internal {
        emit Transfer(from, to, tokenAmount);
        emit TransferShares(from, to, sharesAmount);
    }
function transferShares(address recipient, uint256 sharesAmount) external returns (uint256) {
        _transferShares(msg.sender, recipient, sharesAmount);
        uint256 tokensAmount = _amountByShares(sharesAmount);
        _emitTransferEvents(msg.sender, recipient, tokensAmount, sharesAmount);
        return tokensAmount;
    }
function _amountByShares(uint256 sharesAmount) internal view returns (uint256) {
        uint256 totalShares_ = _totalShares;
        if (totalShares_ == 0) {
            return sharesAmount;
        }
        return sharesAmount.mulWad(_totalSupply()).divWad(totalShares_);
    }

business_flow_context:
function unwrap(uint256 wstUsdcAmount) external returns (uint256 stUsdcAmount) {
        stUsdcAmount = _stUsdc.usdByShares(wstUsdcAmount);
        require(stUsdcAmount > 0, Errors.ZeroAmount());

        _burn(msg.sender, wstUsdcAmount);
        StUsdcLite(address(_stUsdc)).transferShares(msg.sender, wstUsdcAmount);
        emit WstUsdcUnwrapped(msg.sender, wstUsdcAmount, stUsdcAmount);
    }
function _transferRewards(address user) internal {
        RewardData storage rewards = _rewardData;
        StakingData storage data = _stakingData[user];

        uint128 rewardsEarned = data.rewardsAccrued;
        if (rewardsEarned > 0) {
            data.rewardsAccrued = 0;
            rewards.lastShares -= rewardsEarned;
            _stUsdc.transferShares(user, rewardsEarned);
        }
    }
function _debit(uint256 _amountLD, uint256 _minAmountLD, uint32 _dstEid)
        internal
        override
        returns (uint256 amountSentLD, uint256 amountReceivedLD)
    {
        // Shares will be sent in order to avoid share loss during travel
        uint256 sharesLD = _sharesByAmount(_amountLD);
        uint256 minSharesLD = _sharesByAmount(_minAmountLD);

        // NOTE: While the variables are named amountSentLD and amountReceivedLD they are denominated in
        //       shares.
        (amountSentLD, amountReceivedLD) = _debitView(sharesLD, minSharesLD, _dstEid);

        uint256 usdToDebit = _amountByShares(amountSentLD);
        _burnShares(msg.sender, amountSentLD);
        _setTotalUsdFloor(_totalUsdFloor - usdToDebit);
    }
function usdByShares(uint256 sharesAmount) public view override returns (uint256) {
        return _amountByShares(sharesAmount);
    }
function _credit(address _to, uint256 _amountToCreditLD, uint32 /*_srcEid*/ )
        internal
        override
        returns (uint256 amountReceivedLD)
    {
        // NOTE: Shares will be received in order to avoid share loss during travel
        //       _amountToCreditLD == sharesToCreditLD
        uint256 usdToCredit = _amountByShares(_amountToCreditLD);
        _mintShares(_to, _amountToCreditLD);
        _setTotalUsdFloor(_totalUsdFloor + usdToCredit);
        return _amountToCreditLD;
    }
function _totalSupply() internal view virtual override returns (uint256) {
        return _totalUsd();
    }

