    // =================== View Functions ===================

    /// @inheritdoc IStUsdcLite
    function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }

    /// @inheritdoc IStUsdcLite
    function lastUsdPerShare() external view returns (uint256) {
        return _lastUsdPerShare;
    }

    /// @inheritdoc IStUsdcLite
    function rewardPerSecond() external view returns (uint256) {
        return _rewardPerSecond;
    }

    /// @inheritdoc IStUsdcLite
    function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }

    // /// @inheritdoc IStUsdcLite
    function lastRateUpdate() public view returns (uint256) {
        return _lastRateUpdate;
    }

    /// @notice Get the total USD value of the protocol
    function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }

    // =================== LayerZero Functions =====================

    function _debit(uint256 _amountLD, uint256 _minAmountLD, uint32 _dstEid)
        internal
        override
        returns (uint256 amountSentLD, uint256 amountReceivedLD)
    {
        // Shares will be sent in order to avoid share loss during travel
        uint256 sharesLD = _sharesByAmount(_amountLD);
        uint256 minSharesLD = _sharesByAmount(_minAmountLD);

        // NOTE: While the variables are named amountSentLD and amountReceivedLD they are denominated in
        //       shares.
        (amountSentLD, amountReceivedLD) = _debitView(sharesLD, minSharesLD, _dstEid);

        uint256 usdToDebit = _amountByShares(amountSentLD);
        _burnShares(msg.sender, amountSentLD);
        _setTotalUsdFloor(_totalUsdFloor - usdToDebit);
    }

    function _credit(address _to, uint256 _amountToCreditLD, uint32 /*_srcEid*/ )
        internal
        override
        returns (uint256 amountReceivedLD)
    {
        // NOTE: Shares will be received in order to avoid share loss during travel
        //       _amountToCreditLD == sharesToCreditLD
        uint256 usdToCredit = _amountByShares(_amountToCreditLD);
        _mintShares(_to, _amountToCreditLD);
        _setTotalUsdFloor(_totalUsdFloor + usdToCredit);
        return _amountToCreditLD;
    }
}

business_flow_code:
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function rewardPerSecond() external view returns (uint256) {
        return _rewardPerSecond;
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }
function _setUsdPerShare(uint256 usdPerShare, uint256 timestamp) internal {
        // solidify the yield from the last 24 hours (stored as floor which will be used to update totalUsdFloor)
        uint256 floor = _totalUsd();
        _lastRateUpdate = timestamp;

        uint256 lastUsdPerShare_ = _lastUsdPerShare;
        if (usdPerShare > lastUsdPerShare_) {
            uint256 yieldPerShare = usdPerShare - lastUsdPerShare_;
            _rewardPerSecond = yieldPerShare.divWad(Constants.ONE_DAY);
        } else if (usdPerShare < lastUsdPerShare_) {
            _rewardPerSecond = 0;
            floor = usdPerShare.mulWad(_totalShares);
        }

        _setTotalUsdFloor(floor);
        _lastUsdPerShare = usdPerShare;
        emit UpdatedUsdPerShare(usdPerShare);
    }

business_flow_context:
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }
function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }
function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }
function totalShares() external view returns (uint256) {
        return _totalShares;
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function totalShares() external view returns (uint256) {
        return _totalShares;
    }

content:
function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }

contract_code:
{
    using SafeERC20 for IERC20;
    using FixedPointMathLib for uint256;

    // =================== Storage ===================
    /// @dev Global reward data
    RewardData private _rewardData;

    /// @notice Total amount of STAKEUP staked
    uint256 private _totalStakeUpStaked;

    /// @notice The last block number when rewards were distributed
    uint256 private _lastRewardBlock;

    /// @dev Mapping of users to their staking data
    mapping(address => StakingData) private _stakingData;

    /// @dev Mapping of users to their last deposit timestamp
    mapping(address => uint256) private _lastDeposit;

    // =================== Immutables ===================
    /// @notice The stUsdc token
    IStUsdc private immutable _stUsdc;

    // =================== Modifiers ===================
    /// @notice Updates the global reward index and available reward balance for StakeUp
    modifier updateIndex() {
        _updateRewardIndex();
        _;
    }

    /// @notice distributes rewards to the users accrued rewards
    modifier distributeRewards() {
        _distributeRewards(msg.sender);
        _;
    }

    /// @notice Only the reward token or the contract itself can call this function
    modifier onlyStUsdc() {
        require(msg.sender == address(_stUsdc), Errors.UnauthorizedCaller());
        _;
    }

    /// @notice Prevents a user from withdrawing their stake within 24 hours of their last deposit
    modifier lock() {
        require(_lastDeposit[msg.sender] <= block.timestamp - Constants.ONE_DAY, Errors.Locked());
        _;
    }

    // ================= Constructor =================
    constructor(address stakeupToken_, address stUsdc_) SUPVesting(stakeupToken_) {
        require(stUsdc_ != address(0), Errors.ZeroAddress());
        _stUsdc = IStUsdc(stUsdc_);
        _lastRewardBlock = block.number;
    }

    // ================== functions ==================
    /// @inheritdoc IStakeUpStaking
    function stake(uint256 stakeupAmount) external override updateIndex distributeRewards {
        _lastDeposit[msg.sender] = block.timestamp;
        _stake(msg.sender, stakeupAmount);
    }

    /// @inheritdoc IStakeUpStaking
    function unstake(uint256 stakeupAmount, bool harvestRewards)
        external
        override
        lock
        nonReentrant
        updateIndex
        distributeRewards
    {
        StakingData storage data = _stakingData[msg.sender];
        require(data.amountStaked != 0, Errors.UserHasNoStake());
        require(stakeupAmount <= data.amountStaked, Errors.InsufficientBalance());

        if (stakeupAmount > data.amountStaked) {
            stakeupAmount = data.amountStaked;
        }

        if (harvestRewards) {
            uint256 rewardAmount = data.rewardsAccrued;
            if (rewardAmount > 0) {
                _transferRewards(msg.sender);
            }
        }

        data.amountStaked -= uint128(stakeupAmount);
        _totalStakeUpStaked -= stakeupAmount;

        emit StakeUpUnstaked(msg.sender, stakeupAmount);
        IERC20(address(_stakeupToken)).safeTransfer(msg.sender, stakeupAmount);
    }

    /// @inheritdoc IStakeUpStaking
    function harvest() public nonReentrant updateIndex {
        uint256 rewardAmount = _distributeRewards(msg.sender);
        require(rewardAmount != 0, Errors.NoRewardsToClaim());
        emit RewardsHarvested(msg.sender, rewardAmount);
        _transferRewards(msg.sender);
    }

    /// @inheritdoc IStakeUpStaking
    function processFees() public payable override onlyStUsdc nonReentrant updateIndex {
        // solhint-ignore-previous-line no-empty-blocks
    }

    /// @inheritdoc IStakeUpStaking
    function claimableRewards(address account) external view override returns (uint256) {
        return _stakingData[account].rewardsAccrued
            + _calculateRewardDelta(_stakingData[account], account, _rewardData.index);
    }

    /// @inheritdoc IStakeUpStaking
    function stakupToken() external view returns (IStakeUpToken) {
        return _stakeupToken;
    }

    /// @inheritdoc IStakeUpStaking
    function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }

    /// @inheritdoc IStakeUpStaking
    function totalStakeUpStaked() external view returns (uint256) {
        return _totalStakeUpStaked;
    }

    /// @inheritdoc IStakeUpStaking
    function rewardData() external view returns (RewardData memory) {
        return _rewardData;
    }

    /// @inheritdoc IStakeUpStaking
    function userStakingData(address user) external view returns (StakingData memory) {
        return _stakingData[user];
    }

    /// @inheritdoc IStakeUpStaking
    function lastRewardBlock() external view returns (uint256) {
        return _lastRewardBlock;
    }

    /// @inheritdoc IStakeUpStaking
    function lastDeposit(address user) external view override returns (uint256) {
        return _lastDeposit[user];
    }

    /// @dev Transfers the staked tokens to the staking contract and updates the user's total staked amount
    function _stake(address user, uint256 amount) internal nonReentrant {
        StakingData storage data = _stakingData[user];
        require(amount != 0, Errors.ZeroTokensStaked());

        data.amountStaked += uint128(amount);
        _totalStakeUpStaked += amount;

        emit StakeUpStaked(user, amount);
        IERC20(address(_stakeupToken)).safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Updates the global reward index and balance for StakeUp
     * @dev This function is called every time a user interacts with the staking contract
     *     to ensure that the reward index is up to date
     * @return The updated global reward index
     */
    function _updateRewardIndex() internal returns (uint256) {
        if (_lastRewardBlock != block.number) {
            _lastRewardBlock = block.number;

            uint256 totalStakeUpLocked = _totalStakeUpStaked + _totalStakeUpVesting;
            RewardData storage rewards = _rewardData;

            uint256 accrued = _stUsdc.sharesOf(address(this)) - rewards.lastShares;

            if (rewards.index == 0) {
                rewards.index = uint128(Constants.INITIAL_REWARD_INDEX);
            }

            if (totalStakeUpLocked != 0) {
                rewards.index += uint128(accrued.divWad(totalStakeUpLocked));
            }

            rewards.lastShares = uint128(rewards.lastShares + accrued);

            return rewards.index;
        } else {
            return _rewardData.index;
        }
    }

    /**
     * @notice Distributes rewards to the user's accrued rewards data
     * @dev This function is called every time a user interacts with the staking contract
     *    to ensure that the user's rewards are up to date. It does not transfer the rewards
     *    to the user, it only updates the user's accrued rewards data.
     * @param user The address of the user to distribute rewards to
     * @return The updated amount of rewards accrued by the user
     */
    function _distributeRewards(address user) internal returns (uint256) {
        if (user == address(0)) revert Errors.ZeroAddress();

        StakingData storage data = _stakingData[user];

        if (data.index == 0) {
            data.index = uint128(Constants.INITIAL_REWARD_INDEX);
        }

        uint256 rewardIndex = _rewardData.index;
        if (rewardIndex == data.index) return 0;

        uint256 rewardDelta = _calculateRewardDelta(data, user, rewardIndex);

        data.index = uint128(rewardIndex);
        data.rewardsAccrued += uint128(rewardDelta);

        return data.rewardsAccrued;
    }

    /**
     * @notice Calculates the reward delta for a user
     * @dev The reward delta is the amount of rewards that a user has accrued since the last time
     *      their rewards were updated.
     * @param userData The user's staking data
     * @param user The users address who's reward delta is being calculated
     * @param globalIndex The global reward index the calculation is occurring at
     */
    function _calculateRewardDelta(StakingData memory userData, address user, uint256 globalIndex)
        internal
        view
        returns (uint256)
    {
        uint256 userIndex = userData.index;

        if (userIndex == 0) {
            userIndex = Constants.INITIAL_REWARD_INDEX;
        }

        if (userIndex == globalIndex || globalIndex == 0) {
            return 0;
        }

        uint256 amountStaked = userData.amountStaked + currentBalance(user);
        uint256 delta = globalIndex - userIndex;

        return amountStaked.mulWad(delta);
    }

    /**
     * @notice Transfers the user's accrued rewards to the user
     * @param user The user to transfer rewards to
     */
    function _transferRewards(address user) internal {
        RewardData storage rewards = _rewardData;
        StakingData storage data = _stakingData[user];

        uint128 rewardsEarned = data.rewardsAccrued;
        if (rewardsEarned > 0) {
            data.rewardsAccrued = 0;
            rewards.lastShares -= rewardsEarned;
            _stUsdc.transferShares(user, rewardsEarned);
        }
    }

    /// @inheritdoc SUPVesting
    function _updateRewardState(address account) internal override updateIndex {
        _distributeRewards(account);
    }
}

business_flow_code:
function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }
function rewardData() external view returns (RewardData memory) {
        return _rewardData;
    }
function totalStakeUpStaked() external view returns (uint256) {
        return _totalStakeUpStaked;
    }

business_flow_context:
function redeemWstUsdc(uint256 amount) external override returns (uint256 assetsRedeemed) {
        _burn(msg.sender, amount);
        uint256 stUsdcAmount = _stUsdc.usdByShares(amount);
        assetsRedeemed = _stUsdc.redeemStUsdc(stUsdcAmount);
        _stUsdcAsset.safeTransfer(msg.sender, assetsRedeemed);
    }
function depositAsset(uint256 amount) external override returns (uint256 amountMinted) {
        _stUsdcAsset.safeTransferFrom(msg.sender, address(this), amount);
        _stUsdcAsset.safeApprove(address(_stUsdc), amount);
        amountMinted = _stUsdc.depositAsset(amount);
        amountMinted = _mintWstUsdc(amountMinted);
    }
function depositTby(uint256 tbyId, uint256 amount) external override returns (uint256 amountMinted) {
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
        amountMinted = _stUsdc.depositTby(tbyId, amount);

        uint256 supStartBalance = _sup.balanceOf(address(this));
        amountMinted = _mintWstUsdc(amountMinted);

        // If SUP rewards have been minted, transfer to the user
        uint256 supEndBalance = _sup.balanceOf(address(this));
        if (supEndBalance > supStartBalance) {
            uint256 supMinted = supEndBalance - supStartBalance;
            _sup.safeTransfer(msg.sender, supMinted);
        }
    }
function stUsdcPerToken() external view returns (uint256) {
        return _stUsdc.usdByShares(1 ether);
    }
function bridgeByEid(uint32 eid) external view returns (bytes32) {
        return _wstUsdcBridges[eid];
    }
function _bridgeStUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 stUsdcAmount,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) internal returns (LzBridgeReceipt memory bridgingReceipt) {
        SendParam memory sendParam =
            _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings.options);

        (MessagingReceipt memory msgReceipt, OFTReceipt memory oftReceipt) =
            IOFT(_stUsdc).send{value: msg.value}(sendParam, settings.fee, settings.refundRecipient);

        bridgingReceipt = LzBridgeReceipt(msgReceipt, oftReceipt);
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function _setSendParam(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 amount,
        uint256 wstUsdcAmount,
        bytes calldata options
    ) internal view returns (SendParam memory) {
        bytes32 wstUsdcBridge = _wstUsdcBridges[dstEid];
        require(wstUsdcBridge != bytes32(0), Errors.ZeroAddress());

        return SendParam({
            dstEid: dstEid,
            to: wstUsdcBridge,
            amountLD: amount,
            minAmountLD: amount,
            extraOptions: options,
            composeMsg: abi.encode(destinationAddress, wstUsdcAmount),
            oftCmd: ""
        });
    }
function _setDelegates(address newDelegate) internal {
        require(newDelegate != address(0), Errors.ZeroAddress());
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).forceSetDelegate(newDelegate);
        ControllerBase(supToken).forceSetDelegate(newDelegate);
        ControllerBase(wstUsdcBridge).forceSetDelegate(newDelegate);
        ControllerBase(keeper).forceSetDelegate(newDelegate);
    }
function _setPeers(uint32 eid, bytes32[4] memory peers) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        IOAppCore(stUsdc).setPeer(eid, peers[0]);
        IOAppCore(supToken).setPeer(eid, peers[1]);
        IOAppCore(wstUsdcBridge).setPeer(eid, peers[2]);
        IOAppCore(keeper).setPeer(eid, peers[3]);
    }
function lzCompose(
        address _oApp,
        bytes32, /*_guid*/
        bytes calldata _message,
        address, /*Executor*/
        bytes calldata /*Executor Data*/
    ) external payable override {
        if (_oApp != _stUsdc) revert Errors.InvalidOApp();
        if (msg.sender != address(endpoint)) revert Errors.UnauthorizedCaller();

        bytes memory _composeMsgContent = OFTComposeMsgCodec.composeMsg(_message);

        (bytes32 destinationAddressBytes32, uint256 wstUsdcAmount) = abi.decode(_composeMsgContent, (bytes32, uint256));
        address destinationAddress = destinationAddressBytes32.bytes32ToAddress();

        bool success = _deliverWstUsdc(destinationAddress, wstUsdcAmount);
        if (!success) revert Errors.LZComposeFailed();
    }
function wstUsdcByStUsdc(uint256 stUsdcAmount) external view returns (uint256) {
        return _stUsdc.sharesByUsd(stUsdcAmount);
    }
function unwrap(uint256 wstUsdcAmount) external returns (uint256 stUsdcAmount) {
        stUsdcAmount = _stUsdc.usdByShares(wstUsdcAmount);
        require(stUsdcAmount > 0, Errors.ZeroAmount());

        _burn(msg.sender, wstUsdcAmount);
        StUsdcLite(address(_stUsdc)).transferShares(msg.sender, wstUsdcAmount);
        emit WstUsdcUnwrapped(msg.sender, wstUsdcAmount, stUsdcAmount);
    }
function tokensPerStUsdc() external view returns (uint256) {
        return _stUsdc.sharesByUsd(1 ether);
    }
function _setBridgeOperator(address newBridgeOperator) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).setBridgeOperator(newBridgeOperator);
        ControllerBase(supToken).setBridgeOperator(newBridgeOperator);
        ControllerBase(wstUsdcBridge).setBridgeOperator(newBridgeOperator);
        ControllerBase(keeper).setBridgeOperator(newBridgeOperator);
    }
function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata _message,
        address _executor,
        bytes calldata _extraData
    ) internal virtual override {
        super._lzReceive(_origin, _guid, _message, _executor, _extraData);
        (uint256 newUsdPerShare, uint256 timestamp) = _decodeUsdPerShare(_message);
        IStUsdc(_stUsdc).setUsdPerShare(newUsdPerShare, timestamp);
    }
function setWstUsdcBridge(uint32 eid, bytes32 bridge) external onlyOwner {
        require(bridge != bytes32(0), Errors.ZeroAddress());
        (,, address wstUsdcBridge,) = _decodeContracts();
        IWstUsdcBridge(wstUsdcBridge).setWstUsdcBridge(eid, bridge);
    }
function wstUsdc() external view returns (IWstUsdc) {
        return _wstUsdc;
    }
function bridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        LzSettings calldata settings
    ) external payable returns (LzBridgeReceipt memory bridgingReceipt) {
        require(destinationAddress != bytes32(0), Errors.ZeroAddress());
        require(wstUsdcAmount > 0, Errors.ZeroAmount());

        _wstUsdc.transferFrom(msg.sender, address(this), wstUsdcAmount);
        uint256 stUsdcAmount = _wstUsdc.unwrap(wstUsdcAmount);

        emit WstUsdcBridged(endpoint.eid(), dstEid, wstUsdcAmount);
        bridgingReceipt = _bridgeStUsdc(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, settings);
    }
function wrap(uint256 stUsdcAmount) external returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _mintWstUsdc(stUsdcAmount);
        ERC20(address(_stUsdc)).transferFrom(msg.sender, address(this), stUsdcAmount);
        emit StUsdcWrapped(msg.sender, stUsdcAmount, wstUsdcAmount);
    }
function stUsdcByWstUsdc(uint256 wstUsdcAmount) external view returns (uint256) {
        return _stUsdc.usdByShares(wstUsdcAmount);
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function _decodeContracts()
        internal
        view
        returns (address stUsdc, address supToken, address wstUsdcBridge, address keeper)
    {
        return abi.decode(_stakeUpContracts, (address, address, address, address));
    }
function wstUsdc() external view returns (address) {
        return address(_wstUsdc);
    }
function _mintWstUsdc(uint256 amount) internal returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _stUsdc.sharesByUsd(amount);
        require(wstUsdcAmount > 0, Errors.ZeroAmount());
        _mint(msg.sender, wstUsdcAmount);
    }
function quoteBridgeWstUsdc(
        uint32 dstEid,
        bytes32 destinationAddress,
        uint256 wstUsdcAmount,
        bytes calldata options
    ) external view returns (MessagingFee memory fee) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        SendParam memory sendParam = _setSendParam(dstEid, destinationAddress, stUsdcAmount, wstUsdcAmount, options);
        return IOFT(_stUsdc).quoteSend(sendParam, false);
    }
function stUsdc() external view override returns (IStUsdc) {
        return _stUsdc;
    }
function setWstUsdcBridge(uint32 eid, bytes32 bridge) external override onlyBridgeOperator {
        require(eid != 0, Errors.InvalidPeerID());
        require(bridge != bytes32(0), Errors.ZeroAddress());
        _wstUsdcBridges[eid] = bridge;
        emit WstUsdcBridgeSet(eid, bridge);
    }
function _deliverWstUsdc(address destinationAddress, uint256 wstUsdcAmount) internal returns (bool) {
        uint256 stUsdcAmount = IStUsdcLite(_stUsdc).usdByShares(wstUsdcAmount);
        IERC20(_stUsdc).approve(address(_wstUsdc), stUsdcAmount);
        wstUsdcAmount = _wstUsdc.wrap(stUsdcAmount);
        return _wstUsdc.transfer(destinationAddress, wstUsdcAmount);
    }
function stUsdc() external view override returns (IStUsdc) {
        return _stUsdc;
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }

