business_flow_context:
function _mintRewards(IBloomPool pool, uint256 tbyId, uint256 amount) internal {
        uint256 mintRewardsRemaining = _mintRewardsRemaining;
        if (mintRewardsRemaining > 0) {
            uint256 maxRewards = _calculateRewards(pool, tbyId, amount);
            uint256 eligibleAmount = Math.min(maxRewards, mintRewardsRemaining);
            _mintRewardsRemaining -= eligibleAmount;
            _stakeupToken.mintRewards(msg.sender, eligibleAmount);
        }
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }
function depositAsset(uint256 amount) external override returns (uint256 amountMinted) {
        _stUsdcAsset.safeTransferFrom(msg.sender, address(this), amount);
        _stUsdcAsset.safeApprove(address(_stUsdc), amount);
        amountMinted = _stUsdc.depositAsset(amount);
        amountMinted = _mintWstUsdc(amountMinted);
    }
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }
function _mintWstUsdc(uint256 amount) internal returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _stUsdc.sharesByUsd(amount);
        require(wstUsdcAmount > 0, Errors.ZeroAmount());
        _mint(msg.sender, wstUsdcAmount);
    }
function _distributePokeRewards() internal {
        if (_pokeRewardsRemaining > 0) {
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                Constants.POKE_REWARDS, _startTimestamp, _pokeRewardsRemaining, false
            );

            if (amount > 0) {
                amount = Math.min(amount, _pokeRewardsRemaining);
                _pokeRewardsRemaining -= amount;
                IStakeUpToken(_stakeupToken).mintRewards(msg.sender, amount);
            }
        }
    }
function depositTby(uint256 tbyId, uint256 amount) external override returns (uint256 amountMinted) {
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
        amountMinted = _stUsdc.depositTby(tbyId, amount);

        uint256 supStartBalance = _sup.balanceOf(address(this));
        amountMinted = _mintWstUsdc(amountMinted);

        // If SUP rewards have been minted, transfer to the user
        uint256 supEndBalance = _sup.balanceOf(address(this));
        if (supEndBalance > supStartBalance) {
            uint256 supMinted = supEndBalance - supStartBalance;
            _sup.safeTransfer(msg.sender, supMinted);
        }
    }
function wrap(uint256 stUsdcAmount) external returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _mintWstUsdc(stUsdcAmount);
        ERC20(address(_stUsdc)).transferFrom(msg.sender, address(this), stUsdcAmount);
        emit StUsdcWrapped(msg.sender, stUsdcAmount, wstUsdcAmount);
    }
function seedGauges() external initialized nonReentrant {
        CurvePoolData[] memory curvePools = _curvePools;
        SeedTimestamp storage timestamps = _seedTimestamp;
        uint256 length = curvePools.length;

        uint256 timeElapsed = block.timestamp - timestamps.lastSeed;
        if (timestamps.lastSeed != 0 && timeElapsed < Constants.SEED_INTERVAL) {
            revert Errors.TooEarlyToSeed();
        }

        for (uint256 i = 0; i < length; ++i) {
            // If this is the first time seeding the gauge, then register SUP as the reward token
            if (timestamps.lastSeed == 0) {
                timestamps.rewardStart = uint128(block.timestamp);
                ICurvePoolGauge(curvePools[i].curveGauge).add_reward(address(_stakeupToken), address(this));
            }
            // Calculate the amount of rewards to mint
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                curvePools[i].maxRewards, timestamps.rewardStart, curvePools[i].rewardsRemaining, true
            );

            if (amount > 0) {
                amount = Math.min(amount, curvePools[i].rewardsRemaining);
                _curvePools[i].rewardsRemaining -= amount;

                // Mint the rewards and deposit tokens into the gauge
                _stakeupToken.mintRewards(address(this), amount);
                IERC20(address(_stakeupToken)).safeApprove(curvePools[i].curveGauge, amount);
                ICurvePoolGauge(curvePools[i].curveGauge).deposit_reward_token(address(_stakeupToken), amount);

                emit GaugeSeeded(curvePools[i].curveGauge, amount);
            }
        }

        timestamps.lastSeed = uint128(block.timestamp);
    }
function depositTby(uint256 tbyId, uint256 amount) external nonReentrant returns (uint256 amountMinted) {
        IBloomPool pool = _bloomPool;
        require(amount > 0, Errors.ZeroAmount());
        require(!pool.isTbyRedeemable(tbyId), Errors.RedeemableTbyNotAllowed());

        amountMinted = _calculateTbyMintAmount(pool, tbyId, amount);

        _deposit(amountMinted);
        // Calculate & mint SUP mint rewards to users.
        _mintRewards(pool, tbyId, amount);

        emit TbyDeposited(msg.sender, tbyId, amount, amountMinted);
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
    }
function _calculateTbyMintAmount(IBloomPool pool, uint256 tbyId, uint256 amount) internal view returns (uint256) {
        uint256 tbyStart = pool.tbyMaturity(tbyId).start;
        uint256 rate = pool.getRate(tbyId);

        // If the TBY has been minted for more than 24 hours and is greater than 1e18, then we discount the rate by a factor of 24 hours.
        //   (if the rate is greater than 1e18)
        uint256 timeElapsed = block.timestamp - tbyStart;
        if (timeElapsed > Constants.ONE_DAY) {
            if (rate > Math.WAD) {
                uint256 adjustedRate =
                    Math.WAD + ((rate - Math.WAD).mulWad(timeElapsed - Constants.ONE_DAY).divWad(timeElapsed));
                return amount.mulWad(adjustedRate) * _scalingFactor;
            }
            return amount.mulWad(rate) * _scalingFactor;
        }

        // If the TBY has been minted for less than or equal to 24 hours, then we mint 1:1
        return (rate >= Math.WAD) ? amount * _scalingFactor : amount.mulWad(rate) * _scalingFactor;
    }
function _mintShares(address recipient, uint256 sharesAmount) internal virtual returns (uint256 newTotalShares) {
        require(recipient != address(0), Errors.ZeroAddress());

        newTotalShares = _totalShares + sharesAmount;
        _totalShares = newTotalShares;

        _shares[recipient] = _shares[recipient] + sharesAmount;
        _emitTransferEvents(address(0), recipient, _amountByShares(sharesAmount), sharesAmount);
    }
function _credit(address _to, uint256 _amountToCreditLD, uint32 /*_srcEid*/ )
        internal
        override
        returns (uint256 amountReceivedLD)
    {
        // NOTE: Shares will be received in order to avoid share loss during travel
        //       _amountToCreditLD == sharesToCreditLD
        uint256 usdToCredit = _amountByShares(_amountToCreditLD);
        _mintShares(_to, _amountToCreditLD);
        _setTotalUsdFloor(_totalUsdFloor + usdToCredit);
        return _amountToCreditLD;
    }

