function _distributeRewards(address user) internal returns (uint256) {
        if (user == address(0)) revert Errors.ZeroAddress();

        StakingData storage data = _stakingData[user];

        if (data.index == 0) {
            data.index = uint128(Constants.INITIAL_REWARD_INDEX);
        }

        uint256 rewardIndex = _rewardData.index;
        if (rewardIndex == data.index) return 0;

        uint256 rewardDelta = _calculateRewardDelta(data, user, rewardIndex);

        data.index = uint128(rewardIndex);
        data.rewardsAccrued += uint128(rewardDelta);

        return data.rewardsAccrued;
    }
function _transferRewards(address user) internal {
        RewardData storage rewards = _rewardData;
        StakingData storage data = _stakingData[user];

        uint128 rewardsEarned = data.rewardsAccrued;
        if (rewardsEarned > 0) {
            data.rewardsAccrued = 0;
            rewards.lastShares -= rewardsEarned;
            _stUsdc.transferShares(user, rewardsEarned);
        }
    }
function _calculateRewardDelta(StakingData memory userData, address user, uint256 globalIndex)
        internal
        view
        returns (uint256)
    {
        uint256 userIndex = userData.index;

        if (userIndex == 0) {
            userIndex = Constants.INITIAL_REWARD_INDEX;
        }

        if (userIndex == globalIndex || globalIndex == 0) {
            return 0;
        }

        uint256 amountStaked = userData.amountStaked + currentBalance(user);
        uint256 delta = globalIndex - userIndex;

        return amountStaked.mulWad(delta);
    }
function harvest() public nonReentrant updateIndex {
        uint256 rewardAmount = _distributeRewards(msg.sender);
        require(rewardAmount != 0, Errors.NoRewardsToClaim());
        emit RewardsHarvested(msg.sender, rewardAmount);
        _transferRewards(msg.sender);
    }

business_flow_context:
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function stUsdc() external view override returns (IStUsdc) {
        return _stUsdc;
    }
function _transfer(address sender, address recipient, uint256 amount) internal override {
        uint256 sharesToTransfer = _sharesByAmount(amount);
        _transferShares(sender, recipient, sharesToTransfer);
        _emitTransferEvents(sender, recipient, amount, sharesToTransfer);
    }
function transferShares(address recipient, uint256 sharesAmount) external returns (uint256) {
        _transferShares(msg.sender, recipient, sharesAmount);
        uint256 tokensAmount = _amountByShares(sharesAmount);
        _emitTransferEvents(msg.sender, recipient, tokensAmount, sharesAmount);
        return tokensAmount;
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function currentBalance(address account) public view override returns (uint256) {
        return _tokenAllocations[account].currentBalance;
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function _harvest() internal {
        IBloomPool pool = _bloomPool;
        uint256 tbyId = lastRedeemedTbyId();
        // Because we start at type(uint256).max, we need to increment and overflow to 0.
        unchecked {
            tbyId++;
        }
        bool isRedeemable = pool.isTbyRedeemable(tbyId);
        if (!isRedeemable) return;

        // Since users can't deposit TBYs that are redeemable, we can update the last redeemed TBY ID.
        _lastRedeemedTbyId = tbyId;

        uint256 amount = _tby.balanceOf(address(this), tbyId);
        if (amount == 0) return;

        // Redeem TBYs
        pool.redeemLender(tbyId, amount);
    }
function _transfer(address sender, address recipient, uint256 amount) internal override {
        uint256 sharesToTransfer = _sharesByAmount(amount);
        _transferShares(sender, recipient, sharesToTransfer);
        _emitTransferEvents(sender, recipient, amount, sharesToTransfer);
    }

