business_flow_context:
function redeemWstUsdc(uint256 amount) external override returns (uint256 assetsRedeemed) {
        _burn(msg.sender, amount);
        uint256 stUsdcAmount = _stUsdc.usdByShares(amount);
        assetsRedeemed = _stUsdc.redeemStUsdc(stUsdcAmount);
        _stUsdcAsset.safeTransfer(msg.sender, assetsRedeemed);
    }
function depositAsset(uint256 amount) external override returns (uint256 amountMinted) {
        _stUsdcAsset.safeTransferFrom(msg.sender, address(this), amount);
        _stUsdcAsset.safeApprove(address(_stUsdc), amount);
        amountMinted = _stUsdc.depositAsset(amount);
        amountMinted = _mintWstUsdc(amountMinted);
    }
function _transferRewards(address user) internal {
        RewardData storage rewards = _rewardData;
        StakingData storage data = _stakingData[user];

        uint128 rewardsEarned = data.rewardsAccrued;
        if (rewardsEarned > 0) {
            data.rewardsAccrued = 0;
            rewards.lastShares -= rewardsEarned;
            _stUsdc.transferShares(user, rewardsEarned);
        }
    }
function depositTby(uint256 tbyId, uint256 amount) external override returns (uint256 amountMinted) {
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
        amountMinted = _stUsdc.depositTby(tbyId, amount);

        uint256 supStartBalance = _sup.balanceOf(address(this));
        amountMinted = _mintWstUsdc(amountMinted);

        // If SUP rewards have been minted, transfer to the user
        uint256 supEndBalance = _sup.balanceOf(address(this));
        if (supEndBalance > supStartBalance) {
            uint256 supMinted = supEndBalance - supStartBalance;
            _sup.safeTransfer(msg.sender, supMinted);
        }
    }
function stUsdcPerToken() external view returns (uint256) {
        return _stUsdc.usdByShares(1 ether);
    }
function _updateRewardIndex() internal returns (uint256) {
        if (_lastRewardBlock != block.number) {
            _lastRewardBlock = block.number;

            uint256 totalStakeUpLocked = _totalStakeUpStaked + _totalStakeUpVesting;
            RewardData storage rewards = _rewardData;

            uint256 accrued = _stUsdc.sharesOf(address(this)) - rewards.lastShares;

            if (rewards.index == 0) {
                rewards.index = uint128(Constants.INITIAL_REWARD_INDEX);
            }

            if (totalStakeUpLocked != 0) {
                rewards.index += uint128(accrued.divWad(totalStakeUpLocked));
            }

            rewards.lastShares = uint128(rewards.lastShares + accrued);

            return rewards.index;
        } else {
            return _rewardData.index;
        }
    }
function _setDelegates(address newDelegate) internal {
        require(newDelegate != address(0), Errors.ZeroAddress());
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).forceSetDelegate(newDelegate);
        ControllerBase(supToken).forceSetDelegate(newDelegate);
        ControllerBase(wstUsdcBridge).forceSetDelegate(newDelegate);
        ControllerBase(keeper).forceSetDelegate(newDelegate);
    }
function _setPeers(uint32 eid, bytes32[4] memory peers) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        IOAppCore(stUsdc).setPeer(eid, peers[0]);
        IOAppCore(supToken).setPeer(eid, peers[1]);
        IOAppCore(wstUsdcBridge).setPeer(eid, peers[2]);
        IOAppCore(keeper).setPeer(eid, peers[3]);
    }
function wstUsdcByStUsdc(uint256 stUsdcAmount) external view returns (uint256) {
        return _stUsdc.sharesByUsd(stUsdcAmount);
    }
function unwrap(uint256 wstUsdcAmount) external returns (uint256 stUsdcAmount) {
        stUsdcAmount = _stUsdc.usdByShares(wstUsdcAmount);
        require(stUsdcAmount > 0, Errors.ZeroAmount());

        _burn(msg.sender, wstUsdcAmount);
        StUsdcLite(address(_stUsdc)).transferShares(msg.sender, wstUsdcAmount);
        emit WstUsdcUnwrapped(msg.sender, wstUsdcAmount, stUsdcAmount);
    }
function tokensPerStUsdc() external view returns (uint256) {
        return _stUsdc.sharesByUsd(1 ether);
    }
function stUsdc() external view returns (IStUsdc) {
        return _stUsdc;
    }
function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata _message,
        address _executor,
        bytes calldata _extraData
    ) internal virtual override {
        super._lzReceive(_origin, _guid, _message, _executor, _extraData);
        (uint256 newUsdPerShare, uint256 timestamp) = _decodeUsdPerShare(_message);
        IStUsdc(_stUsdc).setUsdPerShare(newUsdPerShare, timestamp);
    }
function _setBridgeOperator(address newBridgeOperator) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).setBridgeOperator(newBridgeOperator);
        ControllerBase(supToken).setBridgeOperator(newBridgeOperator);
        ControllerBase(wstUsdcBridge).setBridgeOperator(newBridgeOperator);
        ControllerBase(keeper).setBridgeOperator(newBridgeOperator);
    }
function setWstUsdcBridge(uint32 eid, bytes32 bridge) external onlyOwner {
        require(bridge != bytes32(0), Errors.ZeroAddress());
        (,, address wstUsdcBridge,) = _decodeContracts();
        IWstUsdcBridge(wstUsdcBridge).setWstUsdcBridge(eid, bridge);
    }
function wstUsdc() external view returns (IWstUsdc) {
        return _wstUsdc;
    }
function wrap(uint256 stUsdcAmount) external returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _mintWstUsdc(stUsdcAmount);
        ERC20(address(_stUsdc)).transferFrom(msg.sender, address(this), stUsdcAmount);
        emit StUsdcWrapped(msg.sender, stUsdcAmount, wstUsdcAmount);
    }
function stUsdcByWstUsdc(uint256 wstUsdcAmount) external view returns (uint256) {
        return _stUsdc.usdByShares(wstUsdcAmount);
    }
function stUsdc() external view returns (address) {
        return _stUsdc;
    }
function _decodeContracts()
        internal
        view
        returns (address stUsdc, address supToken, address wstUsdcBridge, address keeper)
    {
        return abi.decode(_stakeUpContracts, (address, address, address, address));
    }
function _mintWstUsdc(uint256 amount) internal returns (uint256 wstUsdcAmount) {
        wstUsdcAmount = _stUsdc.sharesByUsd(amount);
        require(wstUsdcAmount > 0, Errors.ZeroAmount());
        _mint(msg.sender, wstUsdcAmount);
    }
