function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }

contract_code:
{
    using FpMath for uint256;

    // =================== Storage ===================
    /// @dev Total amount of USD excluding any yield that is accruing during the current day
    uint256 internal _totalUsdFloor;

    /// @dev Last rate update timestamp
    uint256 internal _lastRateUpdate;

    /// @dev The usdPerShare value at the time of the last rate update.
    uint256 internal _lastUsdPerShare;

    /// @dev The rewardPerSecond of yield accrual that is distributed 24 hours after rate updates (per share)
    uint256 internal _rewardPerSecond;

    // =================== Immutables ===================
    /// @dev The Keeper contract that handles cross-chain yield distribution
    StakeUpKeeper internal immutable _keeper;

    // =================== Modifiers ===================
    modifier onlyKeeper() {
        require(msg.sender == address(_keeper), Errors.UnauthorizedCaller());
        _;
    }

    // ================== Constructor ==================
    constructor(address layerZeroEndpoint, address bridgeOperator)
        RebasingOFT("staked USDC", "stUSDC", layerZeroEndpoint, bridgeOperator)
    {
        _lastRateUpdate = block.timestamp;
        _lastUsdPerShare = FpMath.WAD;

        // Deploy the StakeUpKeeper contract
        _keeper = new StakeUpKeeper(address(this), layerZeroEndpoint, bridgeOperator);
    }

    // =================== Functions ==================
    /// @inheritdoc IStUsdcLite
    function setUsdPerShare(uint256 usdPerShare, uint256 timestamp) external onlyKeeper {
        _setUsdPerShare(usdPerShare, timestamp);
    }

    /// @notice Get the number of shares that are equivalent to a specified amount of USD
    function sharesByUsd(uint256 usdAmount) public view override returns (uint256) {
        return _sharesByAmount(usdAmount);
    }

    /// @notice Get the amount of USD that is equivalent to a specified amount of shares
    function usdByShares(uint256 sharesAmount) public view override returns (uint256) {
        return _amountByShares(sharesAmount);
    }

    // =================== Internal Functions ===================

    /**
     * @dev This is used for calculating tokens from shares and vice versa.
     * @dev This function is required to be implemented in a derived contract.
     * @return Total amount of USD controlled by the protocol
     */
    function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }

    /**
     * @dev Set the floor amount of total USD excluding yield accruing from rewardPerSecond.
     * @param amount Amount
     */
    function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }

    /// @dev This is called on the base chain before distributing yield to other chains
    function _setUsdPerShare(uint256 usdPerShare, uint256 timestamp) internal {
        // solidify the yield from the last 24 hours (stored as floor which will be used to update totalUsdFloor)
        uint256 floor = _totalUsd();
        _lastRateUpdate = timestamp;

        uint256 lastUsdPerShare_ = _lastUsdPerShare;
        if (usdPerShare > lastUsdPerShare_) {
            uint256 yieldPerShare = usdPerShare - lastUsdPerShare_;
            _rewardPerSecond = yieldPerShare.divWad(Constants.ONE_DAY);
        } else if (usdPerShare < lastUsdPerShare_) {
            _rewardPerSecond = 0;
            floor = usdPerShare.mulWad(_totalShares);
        }

        _setTotalUsdFloor(floor);
        _lastUsdPerShare = usdPerShare;
        emit UpdatedUsdPerShare(usdPerShare);
    }

    /// @inheritdoc RebasingOFT
    function _totalSupply() internal view virtual override returns (uint256) {
        return _totalUsd();
    }

    // =================== View Functions ===================

    /// @inheritdoc IStUsdcLite
    function totalUsdFloor() external view returns (uint256) {
        return _totalUsdFloor;
    }

    /// @inheritdoc IStUsdcLite
    function lastUsdPerShare() external view returns (uint256) {
        return _lastUsdPerShare;
    }

    /// @inheritdoc IStUsdcLite
    function rewardPerSecond() external view returns (uint256) {
        return _rewardPerSecond;
    }

    /// @inheritdoc IStUsdcLite
    function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }

    // /// @inheritdoc IStUsdcLite
    function lastRateUpdate() public view returns (uint256) {
        return _lastRateUpdate;
    }

    /// @notice Get the total USD value of the protocol
    function totalUsd() external view override returns (uint256) {
        return _totalUsd();
    }

    // =================== LayerZero Functions =====================

    function _debit(uint256 _amountLD, uint256 _minAmountLD, uint32 _dstEid)
        internal
        override
        returns (uint256 amountSentLD, uint256 amountReceivedLD)
    {
        // Shares will be sent in order to avoid share loss during travel
        uint256 sharesLD = _sharesByAmount(_amountLD);
        uint256 minSharesLD = _sharesByAmount(_minAmountLD);

        // NOTE: While the variables are named amountSentLD and amountReceivedLD they are denominated in
        //       shares.
        (amountSentLD, amountReceivedLD) = _debitView(sharesLD, minSharesLD, _dstEid);

        uint256 usdToDebit = _amountByShares(amountSentLD);
        _burnShares(msg.sender, amountSentLD);
        _setTotalUsdFloor(_totalUsdFloor - usdToDebit);
    }

    function _credit(address _to, uint256 _amountToCreditLD, uint32 /*_srcEid*/ )
        internal
        override
        returns (uint256 amountReceivedLD)
    {
        // NOTE: Shares will be received in order to avoid share loss during travel
        //       _amountToCreditLD == sharesToCreditLD
        uint256 usdToCredit = _amountByShares(_amountToCreditLD);
        _mintShares(_to, _amountToCreditLD);
        _setTotalUsdFloor(_totalUsdFloor + usdToCredit);
        return _amountToCreditLD;
    }
}

business_flow_code:
function _setTotalUsdFloor(uint256 amount) internal virtual {
        _totalUsdFloor = amount;
    }
function _setUsdPerShare(uint256 usdPerShare, uint256 timestamp) internal {
        // solidify the yield from the last 24 hours (stored as floor which will be used to update totalUsdFloor)
        uint256 floor = _totalUsd();
        _lastRateUpdate = timestamp;

        uint256 lastUsdPerShare_ = _lastUsdPerShare;
        if (usdPerShare > lastUsdPerShare_) {
            uint256 yieldPerShare = usdPerShare - lastUsdPerShare_;
            _rewardPerSecond = yieldPerShare.divWad(Constants.ONE_DAY);
        } else if (usdPerShare < lastUsdPerShare_) {
            _rewardPerSecond = 0;
            floor = usdPerShare.mulWad(_totalShares);
        }

        _setTotalUsdFloor(floor);
        _lastUsdPerShare = usdPerShare;
        emit UpdatedUsdPerShare(usdPerShare);
    }
function setUsdPerShare(uint256 usdPerShare, uint256 timestamp) external onlyKeeper {
        _setUsdPerShare(usdPerShare, timestamp);
    }
function keeper() external view override returns (StakeUpKeeper) {
        return _keeper;
    }
function _totalUsd() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - _lastRateUpdate;
        uint256 yieldPerShare = timeElapsed >= Constants.ONE_DAY
            ? (_rewardPerSecond.mulWad(Constants.ONE_DAY))
            : (_rewardPerSecond.mulWad(timeElapsed));
        uint256 yield = yieldPerShare.mulWad(_totalShares);
        return _totalUsdFloor + yield;
    }

business_flow_context:
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }
function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function totalShares() external view returns (uint256) {
        return _totalShares;
    }
function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata _message,
        address _executor,
        bytes calldata _extraData
    ) internal virtual override {
        super._lzReceive(_origin, _guid, _message, _executor, _extraData);
        (uint256 newUsdPerShare, uint256 timestamp) = _decodeUsdPerShare(_message);
        IStUsdc(_stUsdc).setUsdPerShare(newUsdPerShare, timestamp);
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function _setBridgeOperator(address newBridgeOperator) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).setBridgeOperator(newBridgeOperator);
        ControllerBase(supToken).setBridgeOperator(newBridgeOperator);
        ControllerBase(wstUsdcBridge).setBridgeOperator(newBridgeOperator);
        ControllerBase(keeper).setBridgeOperator(newBridgeOperator);
    }
function _decodeContracts()
        internal
        view
        returns (address stUsdc, address supToken, address wstUsdcBridge, address keeper)
    {
        return abi.decode(_stakeUpContracts, (address, address, address, address));
    }
function _setDelegates(address newDelegate) internal {
        require(newDelegate != address(0), Errors.ZeroAddress());
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        ControllerBase(stUsdc).forceSetDelegate(newDelegate);
        ControllerBase(supToken).forceSetDelegate(newDelegate);
        ControllerBase(wstUsdcBridge).forceSetDelegate(newDelegate);
        ControllerBase(keeper).forceSetDelegate(newDelegate);
    }
function _setPeers(uint32 eid, bytes32[4] memory peers) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        IOAppCore(stUsdc).setPeer(eid, peers[0]);
        IOAppCore(supToken).setPeer(eid, peers[1]);
        IOAppCore(wstUsdcBridge).setPeer(eid, peers[2]);
        IOAppCore(keeper).setPeer(eid, peers[3]);
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function _deposit(uint256 amount) internal {
        uint256 sharesAmount = sharesByUsd(amount);
        if (sharesAmount == 0) revert Errors.ZeroAmount();

        _mintShares(msg.sender, sharesAmount);
        _globalShares += sharesAmount;
        _setTotalUsdFloor(_totalUsdFloor + amount);
    }
function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _processFee(uint256 fee) internal {
        if (fee > 0) {
            uint256 sharesFeeAmount = sharesByUsd(fee);
            _mintShares(address(_stakeupStaking), sharesFeeAmount);
            _setTotalUsdFloor(_totalUsdFloor + fee);

            _globalShares += sharesFeeAmount;
            emit FeeCaptured(sharesFeeAmount);
            _stakeupStaking.processFees();
        }
    }
function totalShares() external view returns (uint256) {
        return _totalShares;
    }

