function setPeer(uint32 eid, bytes32 peer) public virtual override(ControllerBase, OAppCore) onlyBridgeOperator {
        require(eid != 0, Errors.InvalidPeerID());
        require(peer != bytes32(0), Errors.ZeroAddress());
        peers[eid] = peer;
        emit PeerSet(eid, peer);
    }
function setPeers(uint32 eid, bytes32[4] memory peers) external onlyOwner {
        _setPeers(eid, peers);
    }
function _setPeers(uint32 eid, bytes32[4] memory peers) internal {
        (address stUsdc, address supToken, address wstUsdcBridge, address keeper) = _decodeContracts();

        IOAppCore(stUsdc).setPeer(eid, peers[0]);
        IOAppCore(supToken).setPeer(eid, peers[1]);
        IOAppCore(wstUsdcBridge).setPeer(eid, peers[2]);
        IOAppCore(keeper).setPeer(eid, peers[3]);
    }
function setPeer(uint32 eid, bytes32 peer) external virtual;
function setPeer(uint32 eid, bytes32 peer) public virtual override(ControllerBase, OAppCore) onlyBridgeOperator {
        require(eid != 0, Errors.InvalidPeerID());
        require(peer != bytes32(0), Errors.ZeroAddress());
        peers[eid] = peer;
        emit PeerSet(eid, peer);
    }
function setPeer(uint32 eid, bytes32 peer) external virtual;
function _quoteMessage(uint256 expectedUsdPerShare, uint32[] memory peerEids, bytes memory options)
        internal
        view
        returns (uint256 nativeFee)
    {
        uint256 length = peerEids.length;
        for (uint256 i = 0; i < length; ++i) {
            MessagingFee memory fee =
                _quote(peerEids[i], abi.encode(expectedUsdPerShare, block.timestamp), options, false);
            nativeFee += fee.nativeFee;
        }
    }
function _batchSend(bytes memory message, uint32[] memory peerEids, bytes memory options, address refundRecipient)
        internal
        returns (MessagingReceipt[] memory receipts)
    {
        uint256 providedFee = msg.value;

        uint256 length = peerEids.length;
        receipts = new MessagingReceipt[](length);

        for (uint256 i = 0; i < length; ++i) {
            MessagingReceipt memory receipt =
                _lzSend(peerEids[i], message, options, MessagingFee(providedFee, 0), address(this));
            providedFee -= receipt.fee.nativeFee;
            receipts[i] = receipt;
        }

        // If there is excess fee, refund it to the refundRecipient
        if (providedFee > 0) {
            payable(refundRecipient).transfer(providedFee);
        }
    }
function quoteSync(uint256 expectedUsdPerShare, uint32[] memory peerEids, bytes memory options)
        external
        view
        returns (uint256 nativeFee)
    {
        return _quoteMessage(expectedUsdPerShare, peerEids, options);
    }
function poke(LzSettings calldata settings) external payable nonReentrant {
        uint256 currentTimestamp = block.timestamp;
        uint256 lastUpdate = _lastRateUpdate;
        if (currentTimestamp - lastUpdate < Constants.ONE_DAY) return;

        IBloomPool pool = _bloomPool;

        // Open a lend order in the Bloom Pool to auto-compound USDC
        _autoLendAsset(pool);

        // Calculate the value of USDC and TBYs backed by the contract
        uint256 globalShares_ = _globalShares;
        uint256 protocolValue = _protocolValue(pool);
        uint256 newUsdPerShare = protocolValue.divWad(globalShares_);
        uint256 lastUsdPerShare = _lastUsdPerShare;
        uint256 prevFee = _pendingFee;

        if (newUsdPerShare > lastUsdPerShare) {
            uint256 newPendingFee;
            uint256 highestUsdPerShare = _highestUsdPerShare;
            if (newUsdPerShare > highestUsdPerShare) {
                // Calculate performance fee
                uint256 yieldPerShare = newUsdPerShare - highestUsdPerShare;
                newPendingFee = _calculateFee(yieldPerShare, globalShares_);
                _highestUsdPerShare = newUsdPerShare;
            }
            // Calculate the new total value of the protocol for users
            uint256 userValue = protocolValue - newPendingFee;
            newUsdPerShare = userValue.divWad(globalShares_);
            _pendingFee = newPendingFee;
        }

        // Update USD per share to reflect the new value
        _setUsdPerShare(newUsdPerShare, currentTimestamp);

        uint256 peerLength = _peerEids.length;
        if (peerLength != 0) {
            uint256 lzFee = settings.fee.nativeFee;
            require(msg.value >= lzFee, Errors.InvalidMsgValue());
            _keeper.sync{value: lzFee}(
                newUsdPerShare, currentTimestamp, _peerEids, settings.options, settings.refundRecipient
            );
        }

        // If their is a previous pending fee, we need to distribute it to StakeUpStaking
        if (prevFee != 0) {
            _processFee(prevFee);
        }

        // Harvest matured TBYs and distribute rewards
        _harvest();
        _distributePokeRewards();
    }
function sync(
        uint256 newUsdPerShare,
        uint256 timestamp,
        uint32[] memory peerEids,
        bytes memory options,
        address refundRecipient
    ) external payable onlyStUsdc returns (MessagingReceipt[] memory receipts) {
        return _batchSend(abi.encode(newUsdPerShare, timestamp), peerEids, options, refundRecipient);
    }

