function unstake(uint256 stakeupAmount, bool harvestRewards)
        external
        override
        lock
        nonReentrant
        updateIndex
        distributeRewards
    {
        StakingData storage data = _stakingData[msg.sender];
        require(data.amountStaked != 0, Errors.UserHasNoStake());
        require(stakeupAmount <= data.amountStaked, Errors.InsufficientBalance());

        if (stakeupAmount > data.amountStaked) {
            stakeupAmount = data.amountStaked;
        }

        if (harvestRewards) {
            uint256 rewardAmount = data.rewardsAccrued;
            if (rewardAmount > 0) {
                _transferRewards(msg.sender);
            }
        }

        data.amountStaked -= uint128(stakeupAmount);
        _totalStakeUpStaked -= stakeupAmount;

        emit StakeUpUnstaked(msg.sender, stakeupAmount);
        IERC20(address(_stakeupToken)).safeTransfer(msg.sender, stakeupAmount);
    }

category:
The establishment of the vulnerability primarily relies on the internal state of provided contract variables (`_totalStakeUpStaked` and `_totalStakeUpVesting`) and their manipulation or calculation within the provided functions. There isn't a direct dependency on the behavior of other unknown or external contracts specifically for the establishment of the vulnerability described, as it centers around the inaccurate calculation involving internal variables of the same contract. Therefore, the vulnerability's existence isn't immediately impacted by external calls or states from separate contracts but by the local manipulation and the misrepresented summation of staked and vesting tokens.

