function balanceOf(address account) public view override returns (uint256) {
        return _amountByShares(_shares[account]);
    }
function _amountByShares(uint256 sharesAmount) internal view returns (uint256) {
        uint256 totalShares_ = _totalShares;
        if (totalShares_ == 0) {
            return sharesAmount;
        }
        return sharesAmount.mulWad(_totalSupply()).divWad(totalShares_);
    }
function _totalSupply() internal view virtual returns (uint256);

business_flow_context:
function _liveTbyValue(IBloomPool pool) internal view returns (uint256 value) {
        uint256 startingId = lastRedeemedTbyId();
        // Because we start at type(uint256).max, we need to increment and overflow to 0.
        unchecked {
            startingId++;
        }
        uint256 lastMintedId = pool.lastMintedId();
        if (lastMintedId == type(uint256).max) return 0;
        for (uint256 i = startingId; i <= lastMintedId; ++i) {
            value += pool.getRate(i).mulWad(_tby.balanceOf(address(this), i));
        }
    }
function _harvest() internal {
        IBloomPool pool = _bloomPool;
        uint256 tbyId = lastRedeemedTbyId();
        // Because we start at type(uint256).max, we need to increment and overflow to 0.
        unchecked {
            tbyId++;
        }
        bool isRedeemable = pool.isTbyRedeemable(tbyId);
        if (!isRedeemable) return;

        // Since users can't deposit TBYs that are redeemable, we can update the last redeemed TBY ID.
        _lastRedeemedTbyId = tbyId;

        uint256 amount = _tby.balanceOf(address(this), tbyId);
        if (amount == 0) return;

        // Redeem TBYs
        pool.redeemLender(tbyId, amount);
    }
function redeemStUsdc(uint256 amount) external nonReentrant returns (uint256 assetAmount) {
        require(amount > 0, Errors.ZeroAmount());
        require(balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        uint256 shares = sharesByUsd(amount);
        assetAmount = amount / _scalingFactor;

        uint256 assetBalance = _asset.balanceOf(address(this));
        if (assetBalance < assetAmount) {
            uint256 amountNeeded = assetAmount - assetBalance;
            _tryOrderCancellation(amountNeeded);
            uint256 newAssetBalance = _asset.balanceOf(address(this));
            require(newAssetBalance >= assetAmount, Errors.InsufficientBalance());
        }

        _burnShares(msg.sender, shares);
        _setTotalUsdFloor(_totalUsdFloor - amount);
        _globalShares -= shares;

        emit Redeemed(msg.sender, shares, assetAmount);
        _asset.safeTransfer(msg.sender, assetAmount);
    }
function _autoLendAsset(IBloomPool pool) internal {
        uint256 amount = _asset.balanceOf(address(this));
        if (amount > 0) {
            _asset.safeApprove(address(pool), amount);
            pool.lendOrder(amount);
            emit AssetAutoLent(amount);
        }
    }
function depositTby(uint256 tbyId, uint256 amount) external override returns (uint256 amountMinted) {
        _tby.safeTransferFrom(msg.sender, address(this), tbyId, amount, "");
        amountMinted = _stUsdc.depositTby(tbyId, amount);

        uint256 supStartBalance = _sup.balanceOf(address(this));
        amountMinted = _mintWstUsdc(amountMinted);

        // If SUP rewards have been minted, transfer to the user
        uint256 supEndBalance = _sup.balanceOf(address(this));
        if (supEndBalance > supStartBalance) {
            uint256 supMinted = supEndBalance - supStartBalance;
            _sup.safeTransfer(msg.sender, supMinted);
        }
    }
function _debit(uint256 _amountLD, uint256 _minAmountLD, uint32 _dstEid)
        internal
        override
        returns (uint256 amountSentLD, uint256 amountReceivedLD)
    {
        // Shares will be sent in order to avoid share loss during travel
        uint256 sharesLD = _sharesByAmount(_amountLD);
        uint256 minSharesLD = _sharesByAmount(_minAmountLD);

        // NOTE: While the variables are named amountSentLD and amountReceivedLD they are denominated in
        //       shares.
        (amountSentLD, amountReceivedLD) = _debitView(sharesLD, minSharesLD, _dstEid);

        uint256 usdToDebit = _amountByShares(amountSentLD);
        _burnShares(msg.sender, amountSentLD);
        _setTotalUsdFloor(_totalUsdFloor - usdToDebit);
    }
function usdByShares(uint256 sharesAmount) public view override returns (uint256) {
        return _amountByShares(sharesAmount);
    }
function _credit(address _to, uint256 _amountToCreditLD, uint32 /*_srcEid*/ )
        internal
        override
        returns (uint256 amountReceivedLD)
    {
        // NOTE: Shares will be received in order to avoid share loss during travel
        //       _amountToCreditLD == sharesToCreditLD
        uint256 usdToCredit = _amountByShares(_amountToCreditLD);
        _mintShares(_to, _amountToCreditLD);
        _setTotalUsdFloor(_totalUsdFloor + usdToCredit);
        return _amountToCreditLD;
    }
function _totalSupply() internal view virtual override returns (uint256) {
        return _totalUsd();
    }
function _totalSupply() internal view virtual override returns (uint256) {
        return _totalUsd();
    }
function _totalSupply() internal view virtual override returns (uint256) {
        return _totalUsd();
    }

