        return _stakeupToken;
    }
function stakeUpStaking() external view returns (IStakeUpStaking) {
        return _stakeupStaking;
    }
function seedGauges() external initialized nonReentrant {
        CurvePoolData[] memory curvePools = _curvePools;
        SeedTimestamp storage timestamps = _seedTimestamp;
        uint256 length = curvePools.length;

        uint256 timeElapsed = block.timestamp - timestamps.lastSeed;
        if (timestamps.lastSeed != 0 && timeElapsed < Constants.SEED_INTERVAL) {
            revert Errors.TooEarlyToSeed();
        }

        for (uint256 i = 0; i < length; ++i) {
            // If this is the first time seeding the gauge, then register SUP as the reward token
            if (timestamps.lastSeed == 0) {
                timestamps.rewardStart = uint128(block.timestamp);
                ICurvePoolGauge(curvePools[i].curveGauge).add_reward(address(_stakeupToken), address(this));
            }
            // Calculate the amount of rewards to mint
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                curvePools[i].maxRewards, timestamps.rewardStart, curvePools[i].rewardsRemaining, true
            );

            if (amount > 0) {
                amount = Math.min(amount, curvePools[i].rewardsRemaining);
                _curvePools[i].rewardsRemaining -= amount;

                // Mint the rewards and deposit tokens into the gauge
                _stakeupToken.mintRewards(address(this), amount);
                IERC20(address(_stakeupToken)).safeApprove(curvePools[i].curveGauge, amount);
                ICurvePoolGauge(curvePools[i].curveGauge).deposit_reward_token(address(_stakeupToken), amount);

                emit GaugeSeeded(curvePools[i].curveGauge, amount);
            }
        }

        timestamps.lastSeed = uint128(block.timestamp);
    }
function _distributePokeRewards() internal {
        if (_pokeRewardsRemaining > 0) {
            uint256 amount = StakeUpRewardMathLib._calculateDripAmount(
                Constants.POKE_REWARDS, _startTimestamp, _pokeRewardsRemaining, false
            );

            if (amount > 0) {
                amount = Math.min(amount, _pokeRewardsRemaining);
                _pokeRewardsRemaining -= amount;
                IStakeUpToken(_stakeupToken).mintRewards(msg.sender, amount);
            }
        }
    }
function _mintAndStartVest(address to, uint256 amount) internal {
        require(to != address(0), Errors.InvalidRecipient());
        require(amount > 0, Errors.ZeroAmount());

        _updateGlobalSupply(amount);
        // Set the vesting state for this recipient in the vesting contract & mint tokens
        address stakeupStaking = _stakeupStaking;
        IStakeUpStaking(stakeupStaking).vestTokens(to, amount);
        _mint(stakeupStaking, amount);
    }
function claimAvailableTokens() external returns (uint256) {
        _updateRewardState(msg.sender);

        VestedAllocation storage allocation = _tokenAllocations[msg.sender];

        uint256 amount = availableTokens(msg.sender);

        _totalStakeUpVesting -= amount;
        allocation.currentBalance -= amount;

        if (allocation.currentBalance == 0) {
            delete _tokenAllocations[msg.sender];
        }

        IERC20(address(_stakeupToken)).safeTransfer(msg.sender, amount);

        return amount;
    }
function vestTokens(address account, uint256 amount) external onlySUP {
        require(account != address(0), Errors.ZeroAddress());
        require(amount > 0, Errors.ZeroAmount());

        _updateRewardState(account);
        VestedAllocation storage allocation = _tokenAllocations[account];

        _totalStakeUpVesting += amount;

        // If this is the first time vesting for this account, set initial vesting state
        // Otherwise, update the vesting state
        if (allocation.vestingStartTime == 0) {
            _tokenAllocations[account].vestingStartTime = block.timestamp;
            _tokenAllocations[account].startingBalance = amount;
            _tokenAllocations[account].currentBalance = amount;
        } else {
            _tokenAllocations[account].startingBalance = allocation.startingBalance + amount;
            _tokenAllocations[account].currentBalance = allocation.currentBalance + amount;
        }
    }
function _updateRewardState(address user) internal virtual {}
